    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The bar chart compares the number of US households, measured in millions, across five annual income bands in 2007, 2011 and 2015."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, the distribution was dominated by households earning below $50,000 and by those earning $100,000 or more, while the two middle-income groups were consistently smaller."
            ]
          },
          {
            "parts": [
              "The highest-income category became clearly the largest by 2015, whereas the $75,000–$99,999 group remained the least common throughout."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 2007, about 25 million households earned under $25,000, compared with roughly 27 million in the $25,000–$49,999 bracket."
            ]
          },
          {
            "parts": [
              "Both groups increased by 2011, reaching just under 29 million and around 30 million, respectively."
            ]
          },
          {
            "parts": [
              "By 2015, they had edged down slightly, to approximately 28 million and 29 million, although they were still among the largest categories."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "The remaining three bands showed less uniform movement."
            ]
          },
          {
            "parts": [
              "The number of households earning $50,000–$74,999 stayed almost unchanged at about 21 million in all three years."
            ]
          },
          {
            "parts": [
              "Those in the $75,000–$99,999 range were consistently the smallest group, at around 14–15 million."
            ]
          },
          {
            "parts": [
              "By contrast, households with incomes of at least $100,000 dipped from about 29 million to 28 million in 2011, before rising sharply to approximately 33 million in 2015."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這張柱狀圖比較了 2007 年、 2011 年和 2015 年美國家庭在五個年收入組別中的數量，單位為百萬戶。",
      "整體而言，年收入低於 50,000 美元的家庭以及年收入 100,000 美元或以上的家庭佔比較大，而兩個中等收入組別的家庭數量一直較少。到 2015 年，最高收入組別明顯成為最大的類別；相反， 75,000 至 99,999 美元收入組在整段期間都是最少見的組別。",
      "在 2007 年，約有 2,500 萬戶家庭年收入低於 25,000 美元，而 25,000 至 49,999 美元收入組則約有 2,700 萬戶。到 2011 年，這兩個組別均有所上升，分別達到接近 2,900 萬戶和約 3,000 萬戶。到 2015 年，兩者都輕微回落，分別降至約 2,800 萬戶和 2,900 萬戶，但它們仍然屬於最大的組別之一。",
      "其餘三個收入組別的變化則沒有那麼一致。年收入 50,000 至 74,999 美元的家庭數量在三個年份中幾乎沒有變化，均約為2,100 萬戶。年收入 75,000 至 99,999 美元的家庭一直是最小的組別，數量約為 1,400 萬至1,500 萬戶。相比之下，年收入至少 100,000 美元的家庭數量先從約 2,900 萬戶下降至 2011年的 2,800 萬戶，之後在 2015 年大幅上升至約 3,300 萬戶。"
    ],
