    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The bar chart compares the proportions of residents in Sydney, Melbourne, Brisbane, Adelaide and Hobart who bought fresh or instant coffee, or visited a café for coffee or tea, over the previous four weeks."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, going to a café was the most common habit in most cities, while buying fresh coffee was consistently the least popular option."
            ]
          },
          {
            "parts": [
              "Instant coffee was more widely purchased than fresh coffee in every city, and Adelaide was the only place where café visits did not occupy first position."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "Café-going was especially popular in Melbourne and Hobart, at about 64% and 63% respectively, followed by Sydney, where just over three fifths of residents reported doing so."
            ]
          },
          {
            "parts": [
              "The figures were lower in Brisbane, at around 56%, and Adelaide, at just under 50%, making it the weakest city for café visits."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "In terms of coffee purchases, instant coffee recorded relatively high figures in Hobart and Brisbane, at roughly 54% and 53%."
            ]
          },
          {
            "parts": [
              "Adelaide stood at about 50%, while Melbourne and Sydney were slightly lower, at approximately 48% and 45% respectively."
            ]
          },
          {
            "parts": [
              "By contrast, fresh coffee attracted smaller shares everywhere: around 44% in Sydney, 43% in Melbourne, 39% in Hobart, and only about 34% in Brisbane and 35% in Adelaide."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這張柱狀圖比較了悉尼、墨爾本、布里斯本、阿德萊德和霍巴特居民在過去四星期內購買新鮮咖啡、即溶咖啡，或到咖啡店喝咖啡或茶的比例。",
      "整體而言，在大多數城市中，到咖啡店是最常見的習慣，而購買新鮮咖啡則一直是最不受歡迎的選項。在每個城市中，即溶咖啡的購買比例都高於新鮮咖啡；而阿德萊德是唯一一個咖啡店到訪率沒有排在第一位的城市。",
      "到咖啡店在墨爾本和霍巴特尤其普遍，比例分別約為 64% 和 63% ；其次是悉尼，當地略多於五分之三的居民表示曾這樣做。布里斯本的比例較低，約為 56% ；而阿德萊德則略低於 50% ，因此成為咖啡店到訪率最低的城市。",
      "就咖啡購買而言，即溶咖啡在霍巴特和布里斯本錄得相對較高的比例，分別約為 54% 和 53% 。阿德萊德約為 50% ；而墨爾本和悉尼則稍低，分別約為 48% 和 45% 。相比之下，新鮮咖啡在所有城市中的比例都較低：悉尼約為 44% ，墨爾本約為43% ，霍巴特約為 39% ，而布里斯本和阿德萊德分別只有約 34% 和 35% 。"
    ],
