    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The bar chart compares the percentages of households living in owner-occupied and rented accommodation in England and Wales between 1918 and 2011."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, home ownership followed a clear upward trajectory for most of the period, whereas renting moved in the opposite direction."
            ]
          },
          {
            "parts": [
              "The two categories were equal in 1971, after which ownership became dominant, although it slipped slightly in the final year."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 1918, renting accounted for by far the larger share, at just under four fifths of households, while ownership stood at only about 22%."
            ]
          },
          {
            "parts": [
              "By 1939 and 1953, the rental figure had fallen to around 68%, with owner-occupation rising to roughly 31–32%."
            ]
          },
          {
            "parts": [
              "The gap narrowed further in 1961, when about 42% of households owned their homes, compared with just under 60% that rented."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "The turning point came in 1971, when both categories stood at exactly 50%."
            ]
          },
          {
            "parts": [
              "Thereafter, ownership climbed to approximately 60% in 1981 and almost 70% in 2001, reaching its peak."
            ]
          },
          {
            "parts": [
              "By contrast, renting declined to just over 30% by 2001."
            ]
          },
          {
            "parts": [
              "In 2011, however, the pattern changed modestly: ownership decreased to about 64%, while renting recovered to around 36%."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這張柱狀圖比較了 1918 年至 2011 年間，英格蘭和威爾斯居住在自有住房和租住住房中的家庭比例。",
      "整體而言，在大部分期間，自有住房比例呈現明顯上升趨勢；相反，租住住房比例則朝相反方向變化。這兩個類別在 1971 年持平；其後，自有住房成為主導類別，儘管它在最後一年略有回落。",
      "在 1918 年，租住住房佔明顯較大的比例，略低於五分之四；而自有住房比例僅約為 22% 。到 1939 年和 1953 年，租住住房比例已下降至約 68% ，而自有住房比例則上升至約 31% 至 32% 。到 1961 年，兩者之間的差距進一步收窄，當時約 42% 的家庭擁有自己的住房，而租住住房的比例則略低於 60% 。",
      "轉折點出現在 1971 年，當時兩個類別的比例均為 50% 。此後，自有住房比例在 1981 年上升至約 60% ，並在 2001 年接近 70% ，達最高點。相比之下，租住住房比例到 2001 年下降至略高於 30% 。然而，到 2011 年，這一模式出現了輕微變化：自有住房比例下降至約 64% ，而租住住房比例則回升至約 36% 。"
    ],
