    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The bar chart compares electricity production and consumption in the ten leading countries in 2014, in billions of kilowatt-hours."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, China and the United States were by far the largest producers and users, whereas the other eight countries recorded much lower figures."
            ]
          },
          {
            "parts": [
              "It is also clear that output exceeded consumption in every country except Germany."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "China led the ranking, producing 5,398 billion kWh and consuming a marginally lower 5,322 billion kWh."
            ]
          },
          {
            "parts": [
              "The United States was second, at 4,099 billion kWh for production and 3,866 billion kWh for consumption; despite being well behind China, it remained far ahead of all other nations."
            ]
          },
          {
            "parts": [
              "Russia ranked third, generating 1,057 billion kWh and using 1,038 billion kWh, while Japan followed with 936.2 and 856.7 billion kWh, respectively."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "In the remaining countries, the figures were much smaller."
            ]
          },
          {
            "parts": [
              "India produced 871 billion kWh but consumed only 698.8 billion kWh."
            ]
          },
          {
            "parts": [
              "Canada, France and Brazil showed broadly similar patterns, each generating more electricity than it used, with production between 530.7 and 618.9 billion kWh."
            ]
          },
          {
            "parts": [
              "Germany was the only exception, consuming 582.5 billion kWh compared with output of 526.6 billion kWh."
            ]
          },
          {
            "parts": [
              "South Korea had the lowest totals, at 485.1 and 449.5 billion kWh."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這張柱狀圖比較了 2014 年十大主要國家的電力生產量和耗電量，單位為十億千瓦時。",
      "整體而言，中國和美國是明顯最大的電力生產國和消耗國，而其餘八個國家的數字則低得多。另一個明顯特徵是，除了德國之外，每個國家的電力產量都高於耗電量。",
      "中國位居第一，電力產量為 5,398 十億千瓦時，耗電量則略低，為 5,322 十億千瓦時。美國排名第二，電力產量為 4,099 十億千瓦時，耗電量為 3,866 十億千瓦時；雖然明顯落後於中國，但仍遠遠高於其他所有國家。俄羅斯排名第三，發電量為 1,057 十億千瓦時，用電量為 1,038 十億千瓦時；日本緊隨其後，生產和消耗分別為 936.2 和 856.7 十億千瓦時。",
      "在其餘國家中，相關數字要小得多。印度生產了 871 十億千瓦時的電力，但只消耗了 698.8 十億千瓦時。加拿大、法國和巴西呈現大致相似的模式，三國的發電量都高於耗電量，而產量介乎 530.7 至 618.9 十億千瓦時之間。德國是唯一例外，其耗電量為 582.5 十億千瓦時，高於 526.6 十億千瓦時的產量。南韓的總量最低，產量和耗電量分別為 485.1 和 449.5 十億千瓦時。"
    ],
