    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The bar chart compares the percentages of Australian men and women in six age groups who did regular physical activity in 2010."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, women were more active than men in all age groups except 15–24."
            ]
          },
          {
            "parts": [
              "Male participation was highest among the youngest adults, then fell to a low in middle age before rising gradually, while the female figures remained relatively steady at around 48% to 53%."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In the 15–24 group, 52.8% of men exercised regularly, compared with 47.7% of women."
            ]
          },
          {
            "parts": [
              "The pattern then reversed: male participation dropped to 42.2% among 25- to 34-year-olds and reached its lowest point, 39.5%, in the 35–44 category."
            ]
          },
          {
            "parts": [
              "By contrast, the corresponding female rates rose from 48.9% to 52.5%, creating the largest gender gap, at 13 percentage points."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "In the older age groups, the male figure recovered from 43.1% for those aged 45–54 to 45.1% among 55–64s and 46.7% among people aged 65 and over."
            ]
          },
          {
            "parts": [
              "Women reached their peak in the 45–54 group, at 53.3%, and remained almost as high for 55–64s, at 53.0%."
            ]
          },
          {
            "parts": [
              "In the oldest cohort, however, female participation fell to 47.1%, almost matching the male rate."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這張柱狀圖比較了 2010 年澳洲男性和女性在六個年齡組中定期進行體育活動的百分比。",
      "整體而言，除了 15 至 24 歲組之外，女性在所有年齡組中都比男性更活躍。男性參與率在最年輕的成年人中最高，之後下降至中年低點，然後逐漸回升；相比之下，女性數據則相對穩定，大約維持在 48% 至 53% 之間。",
      "在 15 至 24 歲組中， 52.8% 的男性定期運動，而女性則為 47.7% 。之後，這一模式出現逆轉： 25 至 34 歲男性的參與率下降至 42.2% ，並在 35 至 44 歲組達到最低點，為 39.5% 。相比之下，相應的女性比率從 48.9% 上升至 52.5% ，形成了最大的性別差距，達13 個百分點。",
      "在較年長的年齡組中，男性數據有所回升： 45 至 54 歲組為 43.1% ， 55 至 64 歲組升至 45.1% ， 65 歲及以上組則達到 46.7% 。女性在 45 至 54 歲組達到最高點，為 53.3% ；在 55 至 64 歲組中仍幾乎同樣高，為。然而，在最年長的群體中，女性參與率下降至 47.1% ，幾乎與男性比率相同。"
    ],
