    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The two bar charts compare the destinations of UK graduates and postgraduates who left college in 2008 but did not enter full-time employment."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, further study was the most common route for both groups, whereas voluntary work attracted the fewest students."
            ]
          },
          {
            "parts": [
              "Although the graduate figures were much higher in every category, the overall pattern was broadly similar."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "Among graduates, almost 30,000 continued their education, making further study the clear leading destination."
            ]
          },
          {
            "parts": [
              "Part-time work came next, at 17,735, only slightly ahead of unemployment, which stood at 16,235."
            ]
          },
          {
            "parts": [
              "By contrast, just 3,500 graduates chose voluntary work, less than a quarter of the number without a job and far below the total in further study."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "The same order was evident among postgraduates, though the numbers were smaller."
            ]
          },
          {
            "parts": [
              "Further study again ranked first, with 2,725 students, but it was only narrowly higher than part-time work, at 2,535."
            ]
          },
          {
            "parts": [
              "Unemployment involved 1,625 postgraduates, while voluntary work remained the least common option, at 345."
            ]
          },
          {
            "parts": [
              "Across all four destinations, graduates outnumbered postgraduates substantially, especially in further study, where the difference exceeded 26,000."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這兩張柱狀圖比較了 2008 年英國大學畢業生和研究生離開學院後，在沒有進入全職工作的情況下所選擇的去向。",
      "整體而言，繼續深造是兩組學生最常見的去向，而從事志願工作的人數最少。雖然大學畢業生在每一個類別中人數都遠高於研究生，但整體模式大致相似。",
      "在大學畢業生中，接近 30,000 人繼續學業，使繼續深造成為明顯最多人選擇的去向。兼職工作位居第二，有 17,735 人，只比失業人數 16,235 略高。相比之下，只有 3,500 名畢業生選擇志願工作，這還不到失業人數的四分之一，也遠低於繼續深造的人數。",
      "研究生中也呈現相同的排序，不過人數較少。繼續深造再次排名第一，有 2,725 人，但它只略高於兼職工作的 2,535 人。失業的研究生人數為 1,625 ，而志願工作仍然是最不常見的選項，只有 345 人。在四個去向中，大學畢業生的人數都明顯多於研究生，尤其是在繼續深造方面，兩者差距超過 26,000 人。"
    ],
