    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The bar chart compares the total duration of telephone calls made in the UK, measured in billions of minutes, across three categories between 1995 and 2002."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, local fixed-line calls remained the largest category throughout, despite rising to a peak in the late 1990s and then returning to their initial level."
            ]
          },
          {
            "parts": [
              "By contrast, national and international fixed-line calls increased steadily, while mobile calls, though starting from a very low base, recorded by far the sharpest growth."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 1995, local fixed-line calls accounted for about 72 billion minutes, almost twice the figure for national and international calls, at roughly 37 billion."
            ]
          },
          {
            "parts": [
              "The local category then climbed each year to around 90 billion minutes in 1998 and 1999, before falling back gradually to about 72 billion by 2002."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "The other two categories both followed upward trends."
            ]
          },
          {
            "parts": [
              "National and international fixed-line calls rose consistently from approximately 37 billion minutes in 1995 to just over 60 billion in 2002."
            ]
          },
          {
            "parts": [
              "Mobile calls showed a much more dramatic pattern: after increasing only modestly from about 3 to 12 billion minutes between 1995 and 1999, they surged to roughly 25 billion in 2000 and reached around 45 billion by the final year."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這張柱狀圖比較了 1995 年至 2002 年間英國三類電話通話的總時長，單位為十億分鐘。",
      "整體而言，本地固定電話通話在整段期間一直是最大類別，雖然其通話時長在 1990 年代末升至高點，之後又回到起初水平。相比之下，國內及國際固定電話通話穩定上升；而流動電話通話雖然起點非常低，卻錄得遠遠最顯著的增長。",
      "在 1995 年，本地固定電話通話約佔 720 億分鐘，幾乎是國內及國際固定電話通話的兩倍，後者約為 370 億分鐘。之後，本地通話類別逐年上升，在 1998 年和 1999 年達到約 900 億分鐘，然後逐步回落，到 2002 年降至約 720 億分鐘。",
      "其餘兩個類別都呈現上升趨勢。國內及國際固定電話通話由 1995 年的約 370 億分鐘穩定上升至 2002 年的略高於 600 億分鐘。流動電話通話則呈現更加顯著的變化：在 1995 年至 1999 年間，它只由約 30 億分鐘溫和上升至 120 億分鐘，但在 2000 年急升至約 250 億分鐘，並在最後一年達到約 450 億分鐘。"
    ],
