    "translation": [
      "這張折線圖說明了澳洲墨爾本一所社交中心在 2000 年至 2020 年間五項活動的參加人數。",
      "整體而言，電影俱樂部雖然有輕微波動，但在整個期間一直是參加人數最多的活動。乒乓球的增長幅度明顯最大，並在 2020 年成為第二受歡迎的活動；相反，業餘戲劇在短暫上升後下跌，最後成為最不受歡迎的選項。",
      "在 2000 年，約有 65 人參加電影俱樂部，相比之下，武術約有 36 人，而業餘戲劇約有 26 人。之後，電影俱樂部的人數在 2010 年小幅下降至 60 人，然後在期末回升至約 66人。武術沒有明顯的長期變化：它在 2005 年跌至 32 人後，於 2010 年升至 38 人，最後以約 36 人結束，接近起點水平。",
      "其餘活動的變化則更加明顯。乒乓球在 2000 年至 2010 年間只從 16 人小幅增加至 20 人，但之後迅速上升，在2015 年達到 35 人，並在 2020 年達到約 54 人。音樂表演在圖中最初兩個年份沒有參加者，但之後逐漸上升至 18 人。相比之下，業餘戲劇從 2005 年的峰值 28 人下降至 2020 年的僅 6 人。"
    ],
