    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The line graph compares the percentage of people living in cities in the Philippines, Malaysia, Thailand and Indonesia from 1970 to 2020, with forecasts to 2040."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, all four countries became more urbanised."
            ]
          },
          {
            "parts": [
              "Malaysia rose to and is expected to remain the clear leader, while Indonesia records the fastest long-term growth, moving from the lowest position to second place."
            ]
          },
          {
            "parts": [
              "By contrast, the Philippines fluctuated, and Thailand grew more slowly, becoming the least urbanised country from 2010 onwards."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 1970, the Philippines led slightly, at just over 30%, compared with about 30% in Malaysia."
            ]
          },
          {
            "parts": [
              "The Philippine figure reached nearly 50% in 1990, then declined to just above 40% in 2010, before recovering to roughly 46% in 2020; it is projected to rise to about 56% by 2040."
            ]
          },
          {
            "parts": [
              "Malaysia, however, climbed steadily from around 30% to 60% between 1970 and 2000, and is forecast to exceed 80% by the end."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "Indonesia began at only about 13%, but rose continuously, equalling the Philippines at around 43% in 2010 and reaching just over 50% in 2020."
            ]
          },
          {
            "parts": [
              "It should climb further to the mid-60s, whereas Thailand is expected to grow from just above 30% in 2020 to 50% in 2040."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這張折線圖比較了 1970 年至 2020 年間菲律賓、馬來西亞、泰國和印尼城市人口所佔百分比，並附有到 2040 年的預測。",
      "整體而言，四個國家的城市化程度都提高了。馬來西亞上升後成為、並預計會繼續保持明顯領先的位置；與此同時，印尼錄得最顯著的長期增長，從最低位置升至第二位。相比之下，菲律賓的數據有所波動，而泰國增長較慢，從 2010 年起成為城市化比例最低的國家。",
      "在 1970 年，菲律賓以略高於 30% 的城市人口比例小幅領先，而馬來西亞約為。菲律賓的數據在 1990 年達到接近 50% ，之後在 2010 年下降至略高於 40% ，再於2020 年回升至約 46% ；預計到 2040 年將升至約 56% 。然而，馬來西亞從 1970 年的約 30% 穩步上升至 2000 年的 60% ，並預計在最後一年超過 80% 。",
      "印尼的起點只有約 13% ，但其比例持續上升，在 2010 年以約 43% 追平菲律賓，並於 2020 年達到略高於 50% 。預計印尼會進一步升至 60 多 % 的中段，而泰國則預計會從 2020 年的略高於30% 升至 2040 年的 50% 。"
    ],
