    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The line graph illustrates month-on-month percentage changes in the prices of copper, nickel and zinc in 2014."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, nickel was the most volatile metal, starting with the strongest rise but later recording the steepest fall."
            ]
          },
          {
            "parts": [
              "Copper changed more modestly, whereas zinc ended the year with the highest monthly change."
            ]
          },
          {
            "parts": [
              "All three metals weakened around mid-year before recovering in November and December."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "At the beginning of the year, nickel rose by about 6%, compared with 2% for copper and 1% for zinc."
            ]
          },
          {
            "parts": [
              "In February, nickel remained high at roughly 4%, while zinc peaked at 3%."
            ]
          },
          {
            "parts": [
              "After this, the figures for all three metals fell steadily: by May, nickel and zinc had dropped to around 0.5% and 1% respectively, while copper had slipped to about -0.5%."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "June was the clear low point."
            ]
          },
          {
            "parts": [
              "Nickel plunged to approximately -3%, far below zinc at -1% and copper at about -0.5%."
            ]
          },
          {
            "parts": [
              "From July to September, copper recovered to around 1%, whereas nickel stayed at -1% and zinc hovered near -0.5%."
            ]
          },
          {
            "parts": [
              "In October, nickel slipped again to -2%, but by December all three were positive, with zinc at 2%, copper at around 1.5% and nickel at 1%."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這張折線圖說明了 2014 年銅、鎳和鋅價格相對上個月的百分比變化。",
      "整體而言，鎳是波動最大的金屬，年初錄得最強升幅，但之後又出現最大跌幅。銅的變化較為溫和；相反，鋅在年底錄得最高的月度變化。三種金屬都在年中附近走弱，然後在 11 月和 12 月回升。",
      "年初，鎳上升約 6% ，相比之下，銅和鋅分別上升約 2% 和 1% 。2 月，鎳仍維持在約 4% 的高位，而鋅則達到 3% 的高峰。此後，三種金屬的數字都穩步下降：到 5 月，鎳和鋅分別跌至約 0.5% 和 1% ，而銅則下滑至約 -0.5% 。",
      "6 月是明顯的低點。鎳急跌至約 -3% ，遠低於鋅的 -1% 和銅的約 -0.5% 。從 7 月到 9 月，銅回升至約 1% ；相反，鎳維持在 -1% ，而鋅則徘徊在約 -0.5% 。10 月，鎳再次下滑至 -2% ；但到 12 月，三種金屬都回到正值，其中鋅為 2% ，銅約為 1.5% ，鎳為 1% 。"
    ],
