    "translation": [
      "這張折線圖比較了某一國家在 2011 年至 2018 年間商店關閉和新開商店的數量。",
      "整體而言，新開商店數量呈現明顯下降趨勢，並在最後達到最低點；相反，關店數量則大幅波動。除第一年以及 2015 年關店數出現異常低谷之外，關閉的商店數量多於新開商店數量。",
      "2011 年，新開商店數量遠高於關店數，約為 8,500 間，而關店數約為 6,400 間。之後，新開商店數量在 2012 年幾乎減半至約 4,000 間，然後在 2013 年回升至約5,000 間，並在 2014 年升至略高於 6,000 間。在這次短暫回升之後，新開商店數量在 2015 年和 2016 年回落至 4,000 間， 2017年小幅上升至約 4,200 間，然後在 2018 年下降至約 3,000 間。",
      "關店數量的走勢則較不穩定。該數字從約 6,400 間下降至 2012 年的略低於 6,000 間，之後在 2013 年上升至約7,200 間的高峰。2014 年，關店數仍然維持在較高水平，約為 6,500 間，然後在 2015 年急跌至只有約 500 間。然而，關店數在 2016 年大幅反彈至略高於 5,000 間，之後在最後兩年保持在接近這一水平。"
    ],
