    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The two line charts illustrate changes in the proportion of households owning three electrical appliances and the average time spent on housework each week in one country from 1920 to 2019."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, ownership of all three appliances increased, with refrigerators and vacuum cleaners becoming almost universal by the end of the period."
            ]
          },
          {
            "parts": [
              "Meanwhile, weekly housework fell markedly, from 50 hours to only 10."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 1920, washing machines were the most common appliance, at around 40%, compared with 30% for vacuum cleaners and almost no refrigerator ownership."
            ]
          },
          {
            "parts": [
              "The refrigerator then recorded the sharpest growth, rising to about 55% in 1940 and 90% in 1960, before reaching full ownership in 1980."
            ]
          },
          {
            "parts": [
              "Vacuum cleaners increased more steadily, climbing from 30% to 70% between 1920 and 1960 and reaching 100% by 2000."
            ]
          },
          {
            "parts": [
              "By contrast, washing machines grew more modestly, from 40% to 70% in 1960, dipped to roughly 65% in 1980, and then recovered to about 75% in 2019."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "The second chart shows an opposite pattern."
            ]
          },
          {
            "parts": [
              "Housework declined from 50 hours per week in 1920 to 35 in 1940, then fell further to 20 by 1960."
            ]
          },
          {
            "parts": [
              "Thereafter, the decrease was slower, reaching 15 hours in 1980 and 2000, before dropping to 10 in 2019."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這兩張折線圖說明了 1920 年至 2019 年間，某一國家家庭擁有三種電器的比例變化，以及每週平均花在家務上的時間變化。",
      "整體而言，三種電器的擁有率均有所上升，其中雪櫃和吸塵機到期末時幾乎已普及到所有家庭。與此同時，每週家務時間大幅下降，從 50 小時減少至僅 10 小時。",
      "在 1920 年，洗衣機是最常見的電器，約有 40% 的家庭擁有；相比之下，吸塵機的擁有率為 30% ，而幾乎沒有家庭擁有雪櫃。之後，雪櫃的增長最為顯著，擁有率在 1940 年升至約 55% ， 1960 年升至 90% ，並在 1980 年達到完全普及。吸塵機的擁有率則以較穩定的方式上升，從 1920 年的 30% 增至 1960 年的 70% ，並在 2000 年達到 100% 。相比之下，洗衣機的增長較為溫和，從 1920 年的 40% 升至 1960 年的 70% ，其後在 1980 年下降至約 65% ，最後在 2019 年回升至約 75% 。",
      "第二張圖顯示出相反的趨勢。每週家務時間從 1920 年的 50 小時下降至 1940 年的 35 小時，然後到 1960 年進一步下降至 20 小時。此後，下降速度放緩，在 1980 年和 2000 年達到 15 小時，最後在 2019 年降至 10 小時。"
    ],
