    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The line graph illustrates tourist numbers on a Caribbean island between 2010 and 2017, separating visitors who stayed on cruise ships from those accommodated on the island."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, total arrivals rose substantially, more than tripling across the period."
            ]
          },
          {
            "parts": [
              "Island-based tourists were the larger group at first, but cruise passengers grew much faster and had become the leading category by 2017."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 2010, the island attracted 1 million visitors, about three quarters of whom stayed on the island."
            ]
          },
          {
            "parts": [
              "This total rose steadily to 2 million in 2013, when island-based tourists reached 1.5 million."
            ]
          },
          {
            "parts": [
              "Over the same early period, the cruise-ship figure moved unevenly, increasing from 250,000 to 500,000 in 2011 before falling back to 250,000 in 2012."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "From 2014 onwards, cruise passengers became the main driver of growth."
            ]
          },
          {
            "parts": [
              "Their number climbed from 1 million in 2014 to 1.5 million in 2016, overtaking the island-based group, before reaching 2 million in 2017."
            ]
          },
          {
            "parts": [
              "By contrast, tourists staying on the island remained close to 1.5 million after 2013, except for a slight fall in 2016."
            ]
          },
          {
            "parts": [
              "Consequently, total arrivals plateaued at around 2.75 million in 2015 and 2016, then rose sharply to 3.5 million."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這張折線圖說明了 2010 年至 2017 年間前往某個加勒比海島嶼的遊客人數，並區分了住在遊輪上的遊客和住在島上的遊客。",
      "整體而言，總到訪人數在整段期間大幅上升，增加了超過三倍。起初，住在島上的遊客是較大的群體，但遊輪遊客增長得更快，並在 2017 年成為主要類別。",
      "2010 年，該島吸引了 100 萬名遊客，其中約四分之三住在島上。到 2013 年，總遊客人數穩步上升至 200 萬，而當時住在島上的遊客達到 150 萬。在同一前期階段，遊輪遊客人數變化不太穩定，先從 25 萬上升至 2011 年的 50萬，然後在 2012 年回落至 25 萬。",
      "從 2014 年起，遊輪遊客成為推動增長的主要因素。其人數從 2014 年的 100 萬上升至 2016 年的 150 萬，超過了住在島上的遊客，並在 2017 年達到 200 萬。相比之下， 2013 年之後，住在島上的遊客人數大致維持在接近 150 萬的水平，只是在 2016 年略有下降。因此，總到訪人數在 2015 年和 2016 年停留在約 275 萬，隨後急升至 350 萬。"
    ],
