    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The line graph compares average carbon dioxide emissions per person in the United Kingdom, Sweden, Italy and Portugal from 1967 to 2007, measured in metric tonnes."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, the United Kingdom remained the highest emitter throughout, although its figure declined gradually."
            ]
          },
          {
            "parts": [
              "Sweden also ended lower than it began after reaching a peak in the late 1970s, whereas Italy and Portugal recorded steady growth, with Italy ranking second by 2007."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 1967, the UK produced just under 11 tonnes per person, compared with about 8.7 tonnes in Sweden."
            ]
          },
          {
            "parts": [
              "Sweden then rose to just over 10 tonnes in 1977, almost matching the UK, before falling markedly to around 7 tonnes in 1987 and then to approximately 5.5 tonnes by the final year."
            ]
          },
          {
            "parts": [
              "The UK followed a gentler downward path, slipping from nearly 11 tonnes to about 8.7 tonnes over the same period."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "By contrast, Italy climbed from roughly 4.2 tonnes in 1967 to about 6.3 tonnes in 1977, and then increased further to around 7.7 tonnes in 1997, where it levelled off."
            ]
          },
          {
            "parts": [
              "Portugal, initially the lowest at just over 1 tonne, rose steadily to about 5.5 tonnes in 2007, almost converging with Sweden."
            ]
          }
        ]
      }
    ],
    "translation": [
      "該折線圖比較了 1967 年至 2007 年間英國、瑞典、義大利和葡萄牙的人均二氧化碳排放量，單位為公噸。",
      "整體而言，英國在整段期間一直是人均排放量最高的國家，儘管其數字逐漸下降。瑞典在 1970 年代末達到高峰後，最終排放量低於起點；相反，義大利和葡萄牙均穩定上升，其中義大利到 2007 年排名第二。",
      "1967 年，英國人均二氧化碳排放量略低於 11 公噸，而瑞典約為 8.7 公噸。瑞典隨後在 1977 年升至略高於 10 公噸，幾乎追平英國，之後在 1987 年大幅下降至約 7 公噸，並在最後一年降至約 5.5 公噸。英國則呈現較溫和的下降趨勢，在同一期間由接近 11 公噸降至約 8.7 公噸。",
      "相比之下，義大利的人均排放量從 1967 年的約 4.2 公噸上升至 1977 年的約 6.3 公噸，之後進一步升至 1997 年的約 7.7 公噸，並在此後趨於平穩。葡萄牙起初最低，略高於 1 公噸，但到 2007 年穩定上升至約 5.5 公噸，幾乎與瑞典匯合。"
    ],
    "translationSections": [
      {
        "title": "Introduction",
        "subtitle": "引言",
        "tone": "blue",
        "items": [
          {
            "label": "Background（背景）",
            "english": "The line graph compares average carbon dioxide emissions per person in the United Kingdom, Sweden, Italy and Portugal from 1967 to 2007, measured in metric tonnes.",
            "chinese": "該折線圖比較了 1967 年至 2007 年間英國、瑞典、義大利和葡萄牙的人均二氧化碳排放量，單位為公噸。"
          }
        ]
      },
      {
        "title": "Overview",
        "subtitle": "總覽",
        "tone": "green",
        "items": [
          {
            "label": "Main Feature 1（主要特徵）",
            "english": "Overall, the United Kingdom remained the highest emitter throughout, although its figure declined gradually.",
            "chinese": "整體而言，英國在整段期間一直是人均排放量最高的國家，儘管其數字逐漸下降。"
          },
          {
            "label": "Main Feature 2（主要特徵）",
            "english": "Sweden also ended lower than it began after reaching a peak in the late 1970s, whereas Italy and Portugal recorded steady growth, with Italy ranking second by 2007.",
            "chinese": "瑞典在 1970 年代末達到高峰後，最終排放量低於起點；相反，義大利和葡萄牙均穩定上升，其中義大利到 2007 年排名第二。"
          }
        ]
      },
      {
        "title": "Body Paragraph 1",
        "subtitle": "正文第一段",
        "tone": "orange",
        "items": [
          {
            "label": "Detail 1（細節）",
            "english": "In 1967, the UK produced just under 11 tonnes per person, compared with about 8.7 tonnes in Sweden.",
            "chinese": "1967 年，英國人均二氧化碳排放量略低於 11 公噸，而瑞典約為 8.7 公噸。"
          },
          {
            "label": "Detail 2（細節）",
            "english": "Sweden then rose to just over 10 tonnes in 1977, almost matching the UK, before falling markedly to around 7 tonnes in 1987 and then to approximately 5.5 tonnes by the final year.",
            "chinese": "瑞典隨後在 1977 年升至略高於 10 公噸，幾乎追平英國，之後在 1987 年大幅下降至約 7 公噸，並在最後一年降至約 5.5 公噸。"
          },
          {
            "label": "Detail 3（細節）",
            "english": "The UK followed a gentler downward path, slipping from nearly 11 tonnes to about 8.7 tonnes over the same period.",
            "chinese": "英國則呈現較溫和的下降趨勢，在同一期間由接近 11 公噸降至約 8.7 公噸。"
          }
        ]
      },
      {
        "title": "Body Paragraph 2",
        "subtitle": "正文第二段",
        "tone": "purple",
        "items": [
          {
            "label": "Detail 1（細節）",
            "english": "By contrast, Italy climbed from roughly 4.2 tonnes in 1967 to about 6.3 tonnes in 1977, and then increased further to around 7.7 tonnes in 1997, where it levelled off.",
            "chinese": "相比之下，義大利的人均排放量從 1967 年的約 4.2 公噸上升至 1977 年的約 6.3 公噸，之後進一步升至 1997 年的約 7.7 公噸，並在此後趨於平穩。"
          },
          {
            "label": "Detail 2（細節）",
            "english": "Portugal, initially the lowest at just over 1 tonne, rose steadily to about 5.5 tonnes in 2007, almost converging with Sweden.",
            "chinese": "葡萄牙起初最低，略高於 1 公噸，但到 2007 年穩定上升至約 5.5 公噸，幾乎與瑞典匯合。"
          }
        ]
      }
    ],
