    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The line graph illustrates the amount of energy consumed in the United States from six fuel sources between 1980 and 2030, measured in quadrillion units, with later figures projected."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, petrol and oil remained, and are expected to remain, the dominant fuel source."
            ]
          },
          {
            "parts": [
              "Coal and natural gas formed a second tier, though coal is projected to overtake gas after about 2015, while nuclear, solar/wind and hydropower accounted for only small amounts throughout."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 1980, petrol and oil consumption stood at around 35 quadrillion units, compared with about 20 for natural gas and 16 for coal."
            ]
          },
          {
            "parts": [
              "After dipping to just over 30 in the mid-1980s, petrol and oil rose steadily, reaching roughly 40 by 2005 and a projected 49 by 2030."
            ]
          },
          {
            "parts": [
              "Coal followed a gentler upward path, increasing to about 22 in the mid-1990s, remaining close to that level for several years, and then rising to approximately 32 by the end."
            ]
          },
          {
            "parts": [
              "Natural gas fluctuated around the low twenties before leveling off at about 25 from 2015 onwards."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "The remaining fuels were much less significant."
            ]
          },
          {
            "parts": [
              "Nuclear power climbed gradually from around 4 to about 8–9 units."
            ]
          },
          {
            "parts": [
              "Solar/wind also rose modestly to around 6, whereas hydropower fluctuated slightly and finished at roughly 4."
            ]
          }
        ]
      }
    ],
    "translation": [
      "該折線圖說明了 1980 年至 2030 年間美國六種燃料來源的能源消耗量，單位為千萬億單位，後期數據為預測值。",
      "整體而言，汽油和石油一直是、並預計仍將是最主要的燃料來源。煤和天然氣構成第二梯隊，不過煤預計在約 2015 年後超越天然氣；相反，核能、太陽能／風能和水電在整段期間的消耗量都很小。",
      "1980 年，汽油和石油的消耗量約為 35 千萬億單位，相比之下，天然氣約為 20 ，煤約為 16 。在 1980 年代中期下降至略高於 30 後，汽油和石油的消耗量穩步上升，到 2005年達到約 40 ，並預計到 2030 年達到 49 。煤的上升趨勢較為溫和，在 1990 年代中期增至約 22 ，之後數年保持在接近該水平，最後升至約 32 。天然氣在二十出頭的水平附近波動，之後從 2015 年起穩定在約 25 。",
      "其餘燃料的消耗量明顯小得多。核能由約 4 逐漸上升至約 8 至 9 個單位。太陽能／風能也溫和上升至約 6 ；相反，水電只是輕微波動，最後約為 4 。"
    ],
