    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The line graph illustrates the volume of goods transported in the UK by road, water, rail and pipeline between 1974 and 2002."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, road was consistently the dominant mode and recorded the largest increase."
            ]
          },
          {
            "parts": [
              "Water transport also rose considerably, whereas rail fluctuated and finished only slightly above its initial level."
            ]
          },
          {
            "parts": [
              "Pipeline remained the least-used method, despite steady growth."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 1974, road haulage stood at about 70 million tonnes, compared with roughly 38 million by water and 40 million by rail."
            ]
          },
          {
            "parts": [
              "After a slight rise in 1978 and a dip in 1982, the road figure climbed to just over 80 million tonnes in 1990."
            ]
          },
          {
            "parts": [
              "It then fell marginally in 1994 before rising sharply to almost 100 million tonnes by 2002."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "Water followed a gentler upward trend."
            ]
          },
          {
            "parts": [
              "Its volume increased from just under 40 million tonnes to around 55 million in 1982, stayed near this level until 1994, dipped in 1998, and then recovered to approximately 65 million tonnes."
            ]
          },
          {
            "parts": [
              "By contrast, rail dropped to around 30 million tonnes in 1986 and, despite another dip in 1994, recovered to just over 40 by the end."
            ]
          },
          {
            "parts": [
              "Pipeline transport rose steadily from about 5 to slightly above 20 million tonnes."
            ]
          }
        ]
      }
    ],
    "translation": [
      "該折線圖說明了 1974 年至 2002 年間，英國透過公路、水路、鐵路和管道運輸的貨物量。",
      "整體而言，公路運輸一直是最主要的運輸方式，並錄得最大的絕對增幅。水路運輸也有明顯上升；相反，鐵路運輸有所波動，最後只略高於最初水平。儘管管道運輸穩定增長，但它始終是使用量最低的運輸方式。",
      "在 1974 年，公路貨運量約為 7,000 萬噸，相比之下，水路約為 3,800 萬噸，鐵路約為 4,000 萬噸。在 1978 年小幅上升、 1982 年回落之後，公路運輸量在 1990 年升至略高於 8,000萬噸。隨後，它在 1994 年略微下降，之後大幅上升，到 2002 年接近 1 億噸。",
      "水路運輸呈現較溫和的上升趨勢。其運輸量從略低於 4,000 萬噸上升至 1982 年的約 5,500 萬噸，並一直維持在接近這一水平直到 1994 年，之後在 1998 年下降，最後回升至約 6,500 萬噸。相比之下，鐵路運輸量在 1986 年下降至約 3,000 萬噸；儘管它在 1994 年再次下跌，但到最後回升至略高於 4,000 萬噸。管道運輸量則從約 500 萬噸穩定上升至略高於 2,000 萬噸。"
    ],
