    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The three pie charts compare the average shares of sodium, saturated fat and added sugar consumed at breakfast, lunch, dinner and snack times in the USA."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, dinner is the main contributor to sodium and saturated fat intake, whereas snacks account for the greatest proportion of added sugar."
            ]
          },
          {
            "parts": [
              "Breakfast consistently makes the smallest, or joint-smallest, contribution, while lunch occupies an intermediate position across all three nutrients."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "Breakfast is comparatively light in all categories, representing 14% of sodium and 16% of both saturated fat and added sugar."
            ]
          },
          {
            "parts": [
              "Lunch contributes noticeably more sodium and saturated fat, at 29% and 26% respectively, but its share of added sugar is lower, at 19%."
            ]
          },
          {
            "parts": [
              "Thus, these two earlier meals are generally less dominant than the later ones, although lunch is still a substantial source of sodium."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "Dinner is the most sodium-heavy meal, with its share reaching 43%, and it also leads saturated fat consumption at 37%."
            ]
          },
          {
            "parts": [
              "Its contribution to added sugar, however, is much lower, at 23%."
            ]
          },
          {
            "parts": [
              "Snacks show the reverse pattern: they account for only 14% of sodium and 21% of saturated fat, but dominate added sugar at 42%, almost double the dinner figure."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這三個圓餅圖比較了美國人在早餐、午餐、晚餐和零食時間中攝入的鈉、飽和脂肪和添加糖的平均比例。",
      "整體而言，晚餐是鈉和飽和脂肪攝入的主要來源，而零食則佔添加糖的最大比例。早餐在各項中一直佔最小或並列最小比例，而午餐在三種營養素中大致處於中間位置。",
      "早餐在所有類別中所佔比例都相對較低，分別佔鈉的 14% ，以及飽和脂肪和添加糖的 16% 。午餐所佔的鈉和飽和脂肪比例明顯較高，分別為 29% 和 26% ，但其添加糖比例較低，為 19% 。因此，這兩個較早的餐次整體上不及較晚的餐次突出，不過午餐仍然是鈉的一個重要來源。",
      "晚餐是含鈉比例最高的一餐，佔 43% ，同時也以 37% 成為飽和脂肪比例最高的一餐。然而，它在添加糖方面的比例低得多，只有 23% 。零食則呈現相反模式：它們只佔鈉的 14% 和飽和脂肪的 21% ，但在添加糖方面佔主導地位，達到 42% ，幾乎是晚餐比例的兩倍。"
    ],
