    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The six pie charts compare how water is allocated to agriculture, industry and domestic purposes in six regions of the world."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, agriculture dominates water consumption in four of the six regions, particularly Central Asia, Africa and South East Asia."
            ]
          },
          {
            "parts": [
              "By contrast, industrial use takes the largest share in Europe and North America, while household use remains comparatively small everywhere and never represents the leading category."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In the two regions where industry is the main user, Europe records the highest industrial proportion, at 53%, slightly above North America’s 48%."
            ]
          },
          {
            "parts": [
              "Agricultural use is lower in both places, accounting for 32% in Europe and 39% in North America, whereas domestic consumption is modest, at 15% and 13% respectively."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "The remaining four regions are clearly agriculture-centred."
            ]
          },
          {
            "parts": [
              "Central Asia has the most pronounced reliance on farming, with 88% of water used for this purpose, followed closely by Africa at 84% and South East Asia at 81%."
            ]
          },
          {
            "parts": [
              "South America also devotes a large majority to agriculture, at 71%, although its domestic share, 19%, is noticeably higher than in the other agriculture-dominated regions."
            ]
          },
          {
            "parts": [
              "Industrial use is minimal in these areas, ranging from only 5% in Central Asia to 12% in South East Asia."
            ]
          }
        ]
      }
    ],
    "translation": [
      "六個餅圖比較了世界六個地區的用水如何分配於農業、工業和家庭用途。",
      "整體而言，農業在六個地區中的四個地區佔據用水主導地位，尤其是在中亞、非洲和東南亞。相比之下，工業用途在歐洲和北美佔最大比例，而家庭用水在所有地區都相對較小，並且從未成為主導類別。",
      "在工業是主要用水者的兩個地區中，歐洲的工業用水比例最高，為 53% ，略高於北美的 48% 。在這兩個地區，農業用水比例都較低，歐洲為 32% ，北美為 39% ；而家庭用水比例則較溫和，分別為 15% 和 13% 。",
      "其餘四個地區明顯以農業用水為中心。中亞對農業用水的依賴最明顯，有 88% 的水用於此目的，其次是非洲的 84% 和東南亞的 81% 。南美洲也將絕大部分水用於農業，比例為 71% ；不過其家庭用水比例為 19% ，明顯高於其他以農業為主的地區。在這些地區，工業用水比例很低，從中亞的僅 5% 到東南亞的 12% 不等。"
    ],
