    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The two pie charts compare energy consumption in an average Australian household with the proportions of greenhouse gas emissions produced by each use."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, heating and water heating account for most household energy use, whereas emissions are more evenly distributed."
            ]
          },
          {
            "parts": [
              "Although heating is by far the largest consumer of energy, it produces a much smaller share of emissions; by contrast, other appliances, refrigeration and lighting generate proportionally more greenhouse gas than the energy they use."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In the first chart, heating makes up 42% of total energy consumption, making it the dominant category."
            ]
          },
          {
            "parts": [
              "Water heating is second at 30%, so these two uses together represent almost three quarters of household energy demand."
            ]
          },
          {
            "parts": [
              "The remaining categories are much smaller: other appliances account for 15%, refrigeration for 7%, lighting for 4%, and cooling for just 2%."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "In the emissions chart, water heating is the leading source, at 32%, while other appliances almost double their energy share, producing 28% of emissions."
            ]
          },
          {
            "parts": [
              "Heating, however, is responsible for only 15%."
            ]
          },
          {
            "parts": [
              "Refrigeration and lighting also have higher emission figures, at 14% and 8% respectively, while cooling remains the smallest contributor, at 3%."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這兩個圓餅圖比較澳洲一般家庭的能源消耗，以及每種能源用途所產生的溫室氣體排放比例。",
      "整體而言，供暖和熱水加熱佔家庭能源使用的大部分；相反，溫室氣體排放的分布則更加平均。雖然供暖是迄今最大的能源消耗項目，但它產生的排放比例卻小得多；相反，其他電器、冷藏和照明所產生的溫室氣體比例高於它們所使用的能源比例。",
      "在第一個圖中，供暖佔總能源消耗的 42% ，使其成為主導類別。熱水加熱位居第二，佔 30% ，因此這兩種用途合計幾乎佔家庭能源需求的四分之三。其餘類別則小得多：其他電器佔 15% ，冷藏佔 7% ，照明佔 4% ，而冷氣只佔 2%。",
      "在排放圖中，熱水加熱是最大的來源，佔 32% ；同時，其他電器的排放比例幾乎是其能源使用比例的兩倍，產生 28% 的排放。然而，供暖只佔 15% 的排放。冷藏和照明的排放數字也較高，分別為 14% 和 8% ；而冷氣仍然是最小的排放來源，佔 3% 。"
    ],
