    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The pie charts compare the age profiles of the populations of Yemen and Italy in 2000 and show projections for 2050."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, Yemen had a markedly younger population than Italy in 2000, and this is expected to remain the case in 2050."
            ]
          },
          {
            "parts": [
              "However, both countries are projected to age: the share of children will decline, while older groups, especially those aged 60 and above in Italy, will become more prominent."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In Yemen, children aged 0–14 made up just over half of the population in 2000, at 50.1%, slightly exceeding the 46.3% recorded for people aged 15–59."
            ]
          },
          {
            "parts": [
              "By 2050, this pattern is forecast to reverse, with the working-age group rising to 57.3% and children falling to 37.0%."
            ]
          },
          {
            "parts": [
              "The elderly population will remain comparatively small, though it is expected to increase from 3.6% to 5.7%."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "Italy showed a far older structure."
            ]
          },
          {
            "parts": [
              "In 2000, people aged 15–59 accounted for the largest proportion, at 61.6%, while those over 60 represented 24.1%; children made up only 14.3%."
            ]
          },
          {
            "parts": [
              "By 2050, the 60-plus group is projected to surge to 42.3%, close to the working-age share of 46.2%, whereas the youngest group will shrink slightly to 11.5%."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這些圓餅圖比較了葉門和意大利在 2000 年的人口年齡結構，並展示了 2050 年的預測。",
      "整體而言，葉門在 2000 年的人口明顯比意大利年輕，而這種情況預計在 2050年仍會維持。然而，兩國人口都預計會老化：兒童所佔比例將會下降，而較年長的群體會變得更突出，尤其是意大利 60 歲及以上的人口。",
      "在葉門， 0 至 14 歲兒童在 2000 年佔人口略多於一半，為 50.1% ，稍高於 15 至 59 歲人口的 46.3% 。到 2050 年，這種模式預計會逆轉，工作年齡人口將上升至 57.3% ，而兒童比例則下降至 37.0% 。老年人口仍會相對較少，儘管預計會從 3.6% 上升至 5.7% 。",
      "意大利則呈現出明顯更老化的人口結構。在 2000 年， 15 至 59 歲人口佔最大比例，為 61.6% ； 60 歲以上人口佔 24.1% ；兒童則只佔 14.3% 。到 2050 年， 60 歲以上人口預計會大幅上升至 42.3% ，接近工作年齡人口的46.2% ；相反，最年輕組別將小幅下降至 11.5% 。"
    ],
