    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The three pie charts compare how a UK school allocated its annual budget across five categories in 1981, 1991 and 2001."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, teachers’ salaries consistently took the largest share of spending, although this figure peaked in 1991 before declining slightly."
            ]
          },
          {
            "parts": [
              "Insurance remained the smallest item throughout, while spending on other workers fell steadily and the two material-related categories moved in opposite directions."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 1981, staff pay was the dominant expense, with teachers’ salaries at 40% and other workers’ pay at 28%."
            ]
          },
          {
            "parts": [
              "A decade later, teachers’ salaries rose to half of total expenditure, while spending on other employees fell to 22%, so staff costs together accounted for 72%."
            ]
          },
          {
            "parts": [
              "By 2001, the former had eased to 45% and the latter had dropped more sharply to 15%, reducing the combined salary share to 60%."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "The remaining items changed unevenly."
            ]
          },
          {
            "parts": [
              "Resources such as books increased from 15% in 1981 to 20% in 1991, before falling to 9% in 2001."
            ]
          },
          {
            "parts": [
              "In contrast, furniture and equipment followed the opposite path: it fell from 15% to 5%, then climbed to 23%, becoming the second-largest item in 2001."
            ]
          },
          {
            "parts": [
              "Insurance, although always the smallest category, rose steadily from 2% to 3% and finally to 8%."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這三個圓餅圖比較了一所英國學校在 1981 年、 1991 年和 2001 年如何將年度預算分配到五個項目中。",
      "整體而言，教師薪資一直佔學校開支中最大的比例，不過這一數字在 1991 年達到最高點後略有下降。保險在整段期間一直是最小的支出項目，而其他員工薪資持續下降；同時，兩個與物資和設備相關的項目呈現相反走勢。",
      "在 1981 年，員工薪資是主要支出，其中教師薪資佔 40% ，其他員工薪資佔 28%。十年後，教師薪資上升至總開支的一半，而其他員工薪資則下降至 22% ，因此兩項員工薪資合計佔 72% 。到 2001 年，前者回落至 45% ，後者則更明顯地下降至 15% ，使整體薪資開支比例降至 60% 。",
      "其餘項目的變化並不一致。書本等資源開支由 1981 年的 15% 上升至 1991 年的 20% ，之後在 2001 年下降至 9%。相反，家具和設備開支呈現相反走勢：它先由 15% 下降至 5% ，然後上升至 23%，並在 2001 年成為第二大支出項目。保險雖然一直是最小的類別，但仍由 2% 持續上升至 3% ，最後達到 8% 。"
    ],
