    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The diagram illustrates the process by which bamboo is converted into fabric and, ultimately, clothing items."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, this is a linear, nine-stage manufacturing process, beginning with the cultivation of bamboo plants in spring and ending with finished garments."
            ]
          },
          {
            "parts": [
              "The early stages are concerned with growing and mechanically preparing the bamboo, while the later stages turn the extracted fibres into yarn and woven cloth."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "At the outset, bamboo plants are planted in spring and left to mature until autumn, when they are harvested."
            ]
          },
          {
            "parts": [
              "Once the crop has been collected, the stems are cut into narrow strips."
            ]
          },
          {
            "parts": [
              "These strips are then crushed so that they are reduced to a liquid pulp."
            ]
          },
          {
            "parts": [
              "Following this, the pulp is filtered in order to separate the long fibres from the remaining liquid."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "In the next stage, the extracted fibres are softened through the addition of water and amine oxide."
            ]
          },
          {
            "parts": [
              "After they have been treated in this way, they are spun into yarn."
            ]
          },
          {
            "parts": [
              "The yarn is subsequently woven to produce bamboo fabric."
            ]
          },
          {
            "parts": [
              "Finally, this fabric is made into everyday clothing products, such as socks and T-shirts."
            ]
          }
        ]
      }
    ],
    "translation": [
      "該圖說明竹子如何被轉化成布料，並最終製成衣物。",
      "整體而言，這是一個線性的九階段製造流程，從春季種植竹子開始，以製成成衣結束。前期階段主要涉及竹子的生長和機械處理，而後期階段則把提取出的纖維轉化為紗線和織布。",
      "一開始，竹子在春季被種下，並被留待生長至秋季，然後被收割。當作物被收集後，竹莖會被切成細條。然後，這些竹條會被壓碎，使其變成液態漿料。接著，漿料會被過濾，以便把長纖維從剩餘液體中分離出來。",
      "在下一階段，提取出的纖維會透過加入水和胺氧化物而被軟化。當它們以這種方式處理後，便會被紡成紗線。隨後，紗線會被編織成竹纖維布料。最後，這些布料會被製成日常衣物產品，例如襪子和 T 恤。"
    ],
