    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The diagram illustrates the process by which sugar is produced from sugar cane."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, the production of sugar is a linear, seven-stage process that begins with growing cane and ends with drying and cooling the finished crystals."
            ]
          },
          {
            "parts": [
              "Broadly, it moves from an agricultural phase, involving cultivation and harvesting, to an industrial phase in which juice is extracted, purified, thickened and separated."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "First, sugar cane is grown for 12 to 18 months until it reaches maturity."
            ]
          },
          {
            "parts": [
              "It is then harvested in one of two ways: mechanically, with a vehicle cutting and loading the crop, or manually, with workers cutting the stalks by hand."
            ]
          },
          {
            "parts": [
              "After harvesting, the cane is crushed in a machine, and this step squeezes out the juice required for the later stages."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "The extracted juice is next purified by passing through a limestone filter."
            ]
          },
          {
            "parts": [
              "Once it has been cleaned, it is heated in an evaporator, where excess water is removed and the liquid becomes syrup."
            ]
          },
          {
            "parts": [
              "This syrup is then spun in a centrifuge, which separates sugar crystals from the remaining syrup."
            ]
          },
          {
            "parts": [
              "In the final stage, the crystals are dried and cooled, leaving the finished sugar."
            ]
          }
        ]
      }
    ],
    "translation": [
      "該圖說明糖是如何由甘蔗製成的。",
      "整體而言，糖的生產是一個線性的七階段流程，從種植甘蔗開始，最後以乾燥和冷卻成品糖晶體結束。大致來說，這個流程由涉及栽培和收割的農業階段，轉向工業階段；在工業階段中，汁液會被提取、淨化、濃縮並分離。",
      "首先，甘蔗會被種植十二至十八個月，直到成熟。然後，甘蔗會以兩種方式之一被收割：一種是機械收割，由車輛切割並裝載作物；另一種是人工收割，由工人用手切割甘蔗莖。收割後，甘蔗會在機器中被壓碎，而這一步會擠出後續階段所需的汁液。",
      "提取出的汁液接著會通過石灰石過濾器被淨化。當汁液被清潔後，它會在蒸發器中被加熱；在這一步中，多餘的水分會被去除，而液體會變成糖漿。然後，糖漿會在離心機中旋轉，離心機會把糖晶體從剩餘糖漿中分離出來。在最後階段，糖晶體會被乾燥和冷卻，最終留下成品糖。"
    ],
