    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The diagram illustrates the process by which plastic bottles are recycled and converted into new goods."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, the procedure contains nine main stages, beginning with the disposal of used bottles and ending with the manufacture of various end products."
            ]
          },
          {
            "parts": [
              "It is largely linear, although the production of new bottles means that some items can re-enter the same recycling loop."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "At the initial stage, consumers place discarded plastic bottles in dedicated recycling bins."
            ]
          },
          {
            "parts": [
              "These containers are then emptied by a collection truck, which transports the waste to a recycling centre."
            ]
          },
          {
            "parts": [
              "Once there, the bottles are sorted on a conveyor belt, with suitable items separated from rejected materials."
            ]
          },
          {
            "parts": [
              "The accepted bottles are subsequently compressed into dense blocks, making them easier to handle before further processing."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "In the next phase, the compacted blocks are crushed into small fragments, which are washed to remove impurities."
            ]
          },
          {
            "parts": [
              "The cleaned pieces are fed into a machine and turned into plastic pellets."
            ]
          },
          {
            "parts": [
              "After this, the pellets are heated and transformed into raw material, which is stored in large bundles."
            ]
          },
          {
            "parts": [
              "Finally, this material is used to manufacture a range of products, including new bottles, food containers, T-shirts, shopping bags and pencils."
            ]
          }
        ]
      }
    ],
    "translation": [
      "該圖說明塑膠瓶如何被回收，並轉化為新的商品。",
      "整體而言，這個流程包含九個主要階段，從丟棄使用過的塑膠瓶開始，到製造各種最終產品結束。它大致上是一個線性流程；不過，由於最終產品中包括新的塑膠瓶，一些物品可以重新進入同一個回收循環。",
      "在最初階段，消費者把丟棄的塑膠瓶放入專門的回收箱中。這些回收箱隨後由收集卡車清空，而卡車會把廢棄物運送到回收中心。到達回收中心後，塑膠瓶會在輸送帶上被分類，合適的物品會與被拒收的材料分開。合格的塑膠瓶隨後被壓縮成密集的方塊，以便在進一步加工前更容易處理。",
      "在下一階段，被壓縮的方塊會被粉碎成小碎片，然後被清洗以去除雜質。清洗後的碎片會被送入機器，並轉化成塑膠顆粒。之後，這些塑膠粒會被加熱並轉化為原材料，而原材料會被存放成大型捆包。最後，這些材料會被用來製造一系列產品，包括新的塑膠瓶、食物容器、 T 恤、購物袋和鉛筆。"
    ],
