    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The diagram illustrates the industrial process by which instant noodles are manufactured."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, this is a linear, eight-stage procedure that starts with flour being stored in silos and ends with finished noodle cups being sealed and labelled."
            ]
          },
          {
            "parts": [
              "Broadly, the process can be divided into two phases: preparing and shaping the dough, followed by cooking, flavouring and packaging the product."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "At the beginning, flour is delivered by truck and kept in storage silos."
            ]
          },
          {
            "parts": [
              "It is then transferred to a mixer, where water and oil are added to form dough."
            ]
          },
          {
            "parts": [
              "After this mixture has been prepared, it passes through a series of rollers, which flatten it into thin dough sheets."
            ]
          },
          {
            "parts": [
              "These sheets are subsequently cut into narrow strips, and the strips are shaped into round noodle discs."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "In the second half of the process, the noodle discs are cooked in oil and then dried."
            ]
          },
          {
            "parts": [
              "Once this heating stage has been completed, the dried discs are placed into individual cups."
            ]
          },
          {
            "parts": [
              "Vegetables and spices are added at this point, turning the plain noodles into a complete convenience product."
            ]
          },
          {
            "parts": [
              "Finally, the cups are sealed and labelled before leaving the production line."
            ]
          }
        ]
      }
    ],
    "translation": [
      "該圖說明即食麵是如何透過工業流程被製造出來的。",
      "整體而言，這是一個線性的八階段流程，從麵粉被存放在筒倉開始，以完成的麵杯被密封並貼上標籤結束。大致上，該流程可分為兩個階段：先準備並塑造麵團，然後烹煮、調味並包裝產品。",
      "一開始，麵粉由貨車運送，並被存放在儲存筒倉中。然後，麵粉被轉移到攪拌機中，在那裡加入水和油以形成麵團。當這種混合物準備完成後，它會通過一系列滾軸，被壓平成薄薄的麵團片。隨後，這些麵團片被切成狹長條狀，而這些條狀物再被塑造成圓形麵餅。",
      "在流程的後半部分，麵餅會在油中被烹煮，然後被烘乾。當這個加熱階段完成後，乾燥的麵餅會被放入各自的杯子中。在這個階段，蔬菜和香料會被加入，使原本普通的麵條變成完整的便利食品。最後，杯子在離開生產線前會被密封並貼上標籤。"
    ],
