    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The diagram illustrates how a hydroelectric power station produces electricity by using water stored at different heights."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, the system works as a daily cycle: during the day, water flows downwards from an upper reservoir to generate electricity, while at night the same water is pumped back uphill for reuse."
            ]
          },
          {
            "parts": [
              "A dam and reversible turbines are the central features, and the electricity produced is sent to the national grid."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In the daytime, river water is held in the high-level reservoir behind the dam."
            ]
          },
          {
            "parts": [
              "When the intake is opened, the stored water is released through a sloping pipe towards the power station."
            ]
          },
          {
            "parts": [
              "As it passes through the reversible turbines, these operate a generator, which converts the energy from the moving water into electricity."
            ]
          },
          {
            "parts": [
              "The power is then transmitted by power lines to the national grid, while the used water is discharged into the low-level reservoir."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "At night, the direction of movement is reversed."
            ]
          },
          {
            "parts": [
              "The intake at the dam is closed, and water from the lower reservoir is pumped back through the same turbine system and conduit to the upper reservoir."
            ]
          },
          {
            "parts": [
              "This restores the supply of water, allowing the process to begin again the following day."
            ]
          }
        ]
      }
    ],
    "translation": [
      "該圖說明一座水力發電站如何利用儲存在不同高度的水來產生電力。",
      "整體而言，該系統以每日循環的方式運作：白天，水從上方水庫向下流動以產生電力；夜晚，同一批水會被抽回高處，以便再次使用。水壩和可逆式渦輪機是該系統的核心部件，而產生的電力會被輸送到國家電網。",
      "白天，河水被儲存在水壩後方的高位水庫中。當進水口打開時，儲存的水會通過一條傾斜的管道流向發電站。當水流經可逆式渦輪機時，渦輪機會帶動發電機，而發電機會把水流的能量轉化為電力。隨後，電力會通過電力線輸送到國家電網，而使用過的水則被排入低位水。",
      "到了夜晚，水流方向會反過來。水壩處的進水口會關閉，而低位水庫中的水會通過同一套渦輪系統和導管被抽回高位水庫。這樣可以恢復高位水庫中的水量，使整個過程能夠在第二天再次開始。"
    ],
