    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The diagrams illustrate the life cycle of the salmon, showing the habitats, durations and sizes associated with its main developmental stages."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, salmon pass through three named growth stages—fry, smolt and adult salmon—and move from freshwater rivers to the open sea before returning upstream to reproduce."
            ]
          },
          {
            "parts": [
              "The cycle lasts roughly nine and a half years, with the longest period spent in the sea and most growth occurring during the marine phase."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "At the beginning, salmon eggs are laid in the upper river, where slow-moving water, reeds and small stones provide the spawning environment."
            ]
          },
          {
            "parts": [
              "After approximately five to six months, they hatch into fry, measuring only 3–8 cm."
            ]
          },
          {
            "parts": [
              "These young fish then move downstream to the lower river, a faster-flowing area."
            ]
          },
          {
            "parts": [
              "They remain there for about four years, growing into smolt of around 12–15 cm."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "Following this freshwater stage, the smolt migrate to the open sea."
            ]
          },
          {
            "parts": [
              "This is the longest single phase, lasting about five years, during which they develop into adult salmon."
            ]
          },
          {
            "parts": [
              "By this point, their length has increased markedly to 70–76 cm."
            ]
          },
          {
            "parts": [
              "Finally, the mature fish swim back to the upper river, where they lay eggs and restart the cycle."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這些圖表說明鮭魚的生命週期，展示其主要發育階段所對應的棲息地、所需時間和體型大小。",
      "整體而言，鮭魚會經歷三個有名稱的成長階段 —— 幼魚、銀鮭幼魚和成年鮭魚，並從淡水河流移往開闊海域，之後再逆流返回繁殖。整個週期大約持續九年半，其中最長的階段是在海中度過，而大部分體型增長也發生在海洋階段。",
      "一開始，鮭魚卵被產在上游河段；那裡水流緩慢，並有蘆葦和小石頭，為產卵提供合適環境。大約五至六個月後，魚卵孵化成幼魚，體長只有三至八厘米。這些幼魚接著向下游移動，到達水流較快的下游河段。牠們會在那裡停留大約四年，並成長為體長約十二至十五厘米的銀鮭幼魚。",
      "在完成這個淡水階段後，銀鮭幼魚會遷徙到開闊海域。這是最長的單一階段，持續約五年；在此期間，牠們發育成成年鮭魚。到這個階段，牠們的體長已明顯增加到七十至七十六厘米。最後，成熟的鮭魚會游回上游河段，在那裡產卵並重新開始整個週期。"
    ],
