    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The diagrams illustrate the stages and equipment used to make cement, and how this cement is then used to produce concrete for construction."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, cement manufacture is a multi-stage linear process involving crushing, mixing, heating and grinding, whereas concrete production is much simpler, requiring only the blending of four measured ingredients."
            ]
          },
          {
            "parts": [
              "Gravel accounts for by far the largest share of concrete, while water is the smallest component."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "At the beginning of the cement-making process, limestone and clay are fed into a crusher, where they are reduced to powder."
            ]
          },
          {
            "parts": [
              "This powder is transferred to a mixer and then passes into a rotating heater."
            ]
          },
          {
            "parts": [
              "As the mixture moves through this cylinder, heat is applied from one end, after which the heated material is processed in a grinder."
            ]
          },
          {
            "parts": [
              "The resulting cement is finally packed into bags."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "Concrete production involves fewer stages."
            ]
          },
          {
            "parts": [
              "Cement, sand, gravel and water are all poured into a concrete mixer, which rotates to combine them."
            ]
          },
          {
            "parts": [
              "Gravel, labelled as small stones, makes up half of the mixture, while sand accounts for a further quarter."
            ]
          },
          {
            "parts": [
              "Cement and water constitute 15% and 10%, respectively, before the finished concrete is ready for building work."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這些圖表說明了製造水泥所使用的階段和設備，以及這種水泥如何進一步用於生產建築用混凝土。",
      "整體而言，水泥製造是一個多階段的線性流程，涉及壓碎、混合、加熱和研磨；相比之下，混凝土生產簡單得多，只需要把四種按比例計量的原料混合起來。碎石在混凝土中佔遠遠最大的比例，而水則是最小的組成部分。",
      "在水泥製造過程的開始，石灰石和黏土被送入破碎機，在那裡被壓碎成粉末。這些粉末接著被轉移到混合器，然後進入旋轉加熱器。當混合物通過這個圓筒時，熱量從一端施加；之後，加熱後的材料會在研磨機中進一步處理。最後，製成的水泥被裝入袋中。",
      "混凝土生產涉及的階段較少。水泥、沙、碎石和水全部被倒入混凝土攪拌機中，該機器會旋轉將它們混合。碎石，也就是圖中標註的小石子，佔整個混合物的一半，而沙則佔另外四分之一。水泥和水分別佔 15% 和 10% ，然後製成的混凝土便可用於建築工程。"
    ],
