    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The two plans illustrate the layout of Beechwood Farm in 1950 and the arrangement of the same site today."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, the farm has been transformed from a mainly agricultural site into a more diversified complex."
            ]
          },
          {
            "parts": [
              "The river, main road, farmhouse, chicken enclosure and three crop areas have been retained, whereas the sheep field and basic tracks have given way to roads, visitor facilities and solar panels."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 1950, the western half was used for crops: fruit trees lay in the northwest, with soft fruits and vegetables in adjacent plots to the south."
            ]
          },
          {
            "parts": [
              "A large sheep field occupied most of the north-eastern area."
            ]
          },
          {
            "parts": [
              "Access was provided only by tracks, one running from the main road towards the barn and another leading to the farmhouse."
            ]
          },
          {
            "parts": [
              "The farmhouse stood in the southeast, just above the chickens and inside the bend of the river."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "Today, the crop plots remain in similar positions, but a farm shop and car park have been added near the entrance."
            ]
          },
          {
            "parts": [
              "The former sheep pasture is now divided between a camping field and a solar-panel area, with another car park nearby."
            ]
          },
          {
            "parts": [
              "In the east, holiday cottages have been built above the farmhouse, while the barn has been moved south-west."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這兩張平面圖展示了比奇伍德農場在 1950 年的佈局，以及同一地點現今的安排。",
      "整體而言，該農場已由一個主要用於農業的地點，轉變成一個功能更多元化的綜合場地。河流、主要道路、農舍、雞舍和三個種植區都被保留下來；相反，原本的羊群牧場和簡單小徑則已被道路、遊客設施和太陽能板取代。",
      "在 1950 年，西半部主要用作種植農作物：果樹位於西北部，而漿果類作物和蔬菜則分別位於其南面的相鄰地塊。一大片羊群牧場佔據了東北部的大部分地方。當時的通道只由小徑提供，其中一條由主要道路通往穀倉，另一條則通向農舍。農舍位於東南部，正好在雞舍上方，並坐落於河流彎曲處的內側。",
      "現今，農作物地塊仍大致保留在相似的位置，但入口附近新增了一間農場商店和一個停車場。昔日的羊群牧場現在被分成露營地和太陽能板區，附近還設有另一個停車場。在東部，度假小屋已建於農舍上方，而穀倉則被移至西南方向。"
    ],
