    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The two plans illustrate how Porth Harbour has changed since 2000."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, the harbour has become more developed and visitor-oriented."
            ]
          },
          {
            "parts": [
              "The main changes are the addition of hotel and commercial facilities, the creation of a private beach, the expansion of the dock area, and the relocation of the marina and fishing boats."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "On the western side, the two car parks and the main road are still in place, and the original showers and toilets have been retained beside the northern car park."
            ]
          },
          {
            "parts": [
              "However, the marina for private yachts, formerly in the north-west basin, has been moved southwards to the area once used by fishing boats."
            ]
          },
          {
            "parts": [
              "These boats now occupy the former marina site."
            ]
          },
          {
            "parts": [
              "A second block of showers and toilets has been built near the lower car park, while cafés and shops have been added west of the lifeboat station."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "Further east, the dock has been enlarged with extra mooring space, although the passenger ferries remain nearby."
            ]
          },
          {
            "parts": [
              "The disused castle on the small peninsula has been replaced by a hotel, accessed by an extended road."
            ]
          },
          {
            "parts": [
              "The southern beach is now reserved for hotel guests, whereas the northern public beach and lifeboat station remain largely unchanged."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這兩幅平面圖展示了 Porth Harbour 自 2000 年以來的變化。",
      "整體而言，這個港口變得更加發達，也更以遊客為導向。主要變化包括新增酒店和商業設施、設立私人海灘、擴建碼頭區，以及搬遷私人遊艇碼頭和漁船停泊區。",
      "在西面，兩個停車場和主路仍然保留，而原有的淋浴間和洗手間也保留在北面停車場旁邊。然而，原本位於西北面水域的私人遊艇碼頭，已經向南遷移到原本停泊漁船的區域。這些漁船現在則停泊在原本私人遊艇碼頭所在的位置。另一座淋浴間和洗手間已在較南面的停車場附近建成，而咖啡店和商店則新增在救生艇站的西面。",
      "再往東面，碼頭已經擴建，並增加了停泊空間，不過客運渡輪仍停留在附近。小半島上原本廢棄的城堡已被一間酒店取代，而該酒店可通過延伸道路到達。南面的海灘現在只供酒店住客使用；相反，北面的公共海灘和救生艇站則大致保持不變。"
    ],
