    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The two plans illustrate how the Central Library has been reorganised over the last two decades."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, the library has changed from a mainly book- and reading-based space into a more varied facility, with new areas for technology, events, lectures and refreshments."
            ]
          },
          {
            "parts": [
              "Although the entrance remains in the same position, the central seating has disappeared and several services have been relocated or modernised."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "Twenty years ago, the middle of the library was occupied by tables and chairs, with rooms arranged around it."
            ]
          },
          {
            "parts": [
              "On the left, there was a media room for CDs, videos and computer games in the north-west corner, adult fiction books in the centre, and a reading room for newspapers and magazines near the entrance."
            ]
          },
          {
            "parts": [
              "Today, this side has been fully reorganised: the former media and fiction sections contain children’s fiction books, storytelling space and sofas, while the old reading room has become a computer room."
            ]
          },
          {
            "parts": [
              "A section for all reference books has also been introduced."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "On the right, the old children’s books area has been replaced by a lecture room."
            ]
          },
          {
            "parts": [
              "The former adult non-fiction section now houses adult fiction, an information desk and self-service machines, whereas the old enquiry desk has been converted into a café."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這兩張平面圖說明中央圖書館在過去二十年間如何被重新規劃。",
      "整體而言，該圖書館已經從一個主要以藏書和閱讀為主的空間，轉變成一個功能更為多元的設施，新增了科技、活動、講座和餐飲相關區域。雖然入口仍在相同位置，但中央座位區已經消失，而多項服務已被重新安置或現代化。",
      "二十年前，圖書館中央設有桌椅，周圍則分布著不同房間。在左側，西北角有一個供放置 CDs 、錄像和電腦遊戲的媒體室，中部是成人小說書籍區，靠近入口處則是供閱讀報紙和雜誌的閱覽室。如今，這一側已被完全重新規劃：原來的媒體室和成人小說區變成兒童小說書籍區、講故事活動空間和沙發區，而舊閱覽室則變成電腦室。此外，圖書館亦新增了一個全部參考書區。",
      "在右側，舊兒童書籍區已被講座室取代。原本的成人非小說書籍區現在設有成人小說、資訊服務台和自助服務機，而舊詢問處則已被改建成咖啡館。"
    ],
