    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The two maps compare the present industrial area in Norbiton with the proposed redevelopment of the site."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, the area is set to be transformed from a factory complex into a residential district with public amenities."
            ]
          },
          {
            "parts": [
              "The road network will also be expanded, especially northwards across the river and southwards to the main road, while the river and the main east–west road will largely remain in place."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "Currently, the site is centred on a roundabout south of the river."
            ]
          },
          {
            "parts": [
              "From this junction, one road runs east, with several factories on both sides and another at its far end."
            ]
          },
          {
            "parts": [
              "Other factories stand immediately north and west of the roundabout, and a short road links the junction to the main east–west road."
            ]
          },
          {
            "parts": [
              "The town lies to the west."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "In the future plan, all factories will be removed and replaced mainly by housing."
            ]
          },
          {
            "parts": [
              "Homes will be added west of the roundabout, along the eastern road and, after a bridge is built, north of the river."
            ]
          },
          {
            "parts": [
              "A second roundabout will be constructed on the southern access road."
            ]
          },
          {
            "parts": [
              "Shops, a medical centre, a playground and a school will also be introduced in the southern, eastern and northeastern parts of the site."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這兩幅地圖比較了諾比頓目前的工業區與該地點擬議的未來重建規劃。",
      "整體而言，該區域將由一個工廠群轉變為設有公共設施的住宅區。道路網也將會擴展，尤其會向北跨過河流，並向南連接主要道路；同時，河流和主要東西向道路大致會保留在原位。",
      "目前，該地點以河流以南的一個迴旋處為中心。從這個交匯處，一條道路向東延伸，道路兩側有數間工廠，最東端還有另一間工廠。其他工廠位於迴旋處正北方和西側，而一條短路把這個交匯處連接到主要的東西向道路。城鎮位於西側。",
      "在未來規劃中，所有工廠都將被移除，並主要由住宅取代。住宅將會被增設在迴旋處西側、東面道路沿線，及在橋樑建成後的河流北側。第二個迴旋處將會建在南面的通道上。商店、醫療中心、遊樂場和學校也將分別被引入該地點南部、東部和東北部。"
    ],
