    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The two plans illustrate the current layout of Southwest Airport and the way it is expected to look after redevelopment next year."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, the airport will be substantially enlarged, especially airside, where the existing pier with eight gates will be replaced by a Y-shaped concourse containing eighteen gates and a sky train."
            ]
          },
          {
            "parts": [
              "The terminal will also offer more passenger facilities, although its basic division into departures and arrivals will remain."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "At present, the airport has a small terminal, with departures on the left and arrivals on the right."
            ]
          },
          {
            "parts": [
              "Departing passengers pass through security and passport control before using a walkway to reach eight gates arranged around a rectangular pier."
            ]
          },
          {
            "parts": [
              "The departures area contains only check-in facilities and a café, while arrivals are limited to passport control and customs."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "After redevelopment, the departures hall will include a bag drop, check-in area and café."
            ]
          },
          {
            "parts": [
              "Shops will be added beyond security, leading to the enlarged concourse."
            ]
          },
          {
            "parts": [
              "Instead of a simple walkway, passengers will use a sky train along the main pier, which will branch into two arms and increase the number of gates to eighteen."
            ]
          },
          {
            "parts": [
              "The arrivals side will also gain a café, an ATM and car-hire facilities near the exit."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這兩張平面圖展示了 Southwest Airport 現時的布局，以及它預計在明年重新發展後的樣貌。",
      "整體而言，該機場將會大幅擴建，尤其是在空側區域；現有設有八個登機閘口的登機廊將被一個 Y 形候機大廳取代，當中會有十八個登機閘口和一條空中列車。Main Feature 2 （主要特徵二）。航站樓亦會提供更多乘客服務設施，不過其基本的離境和入境分區將會保留。",
      "目前，該機場有一個較小的航站樓，離境區位於左邊，入境區位於右邊。離境乘客會先通過安檢和護照檢查，然後經由一條步行通道前往圍繞矩形登機廊排列的八個登機閘口。離境區只設有辦理登機手續的設施和一間咖啡店，而入境區則只包括護照檢查和海關。",
      "重新發展後，離境大堂將會包括行李托運處、辦理登機手續區和咖啡店。商店將會增設在安檢之後的位置，並通往擴大的候機大廳。乘客將不再只使用簡單的步行通道，而是會沿著主登機廊乘坐空中列車；該登機廊會分成兩條支線，並把登機閘口數量增加至十八個。入境區一側亦會在出口附近增設咖啡店、自動櫃員機和租車設施。"
    ],
