    "translation": [
      "這兩張平面圖展示了格蘭奇公園在 1920 年首次開放時的布局，以及它今天的安排。",
      "整體而言，該公園已大幅現代化，新增了露天劇場、咖啡館、兒童遊樂區和地下停車場等休閒設施。然而，位於阿諾德大道和埃爾登街的兩個主要入口被保留下來，而玫瑰園仍然是重要元素，儘管它們的數量已減少並被重新安排。",
      "在 1920 年，該公園具有較正式的布局。一座噴泉位於公園中央，而音樂家表演台則佔據西側位置。三個玫瑰園分別位於西北角、東北角和西南角，座位則分布在公園邊緣一帶。公園東半部包含位於東北方的水生植物池，以及位於東南方的玻璃溫室。",
      "如今，中央噴泉已被一個方形玫瑰園取代，而其四周均設有座位。原本的音樂家表演台已被一個更大的露天音樂會劇場取代。在東側，舊有的池塘和玻璃溫室已經消失；取而代之的是咖啡館、兒童遊樂區和水景設施。此外，東南方也新增了一個通往地下停車場的入口。"
    ],
