    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The maps compare road access to a city hospital in 2007 and 2010."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, the layout was substantially reorganised: two roundabouts and a bus station were introduced, and the original combined car park was replaced by separate staff and public parking facilities."
            ]
          },
          {
            "parts": [
              "The three main roads, however, remained in the same positions."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 2007, Hospital Road ran northwards from City Road to the Ring Road, which surrounded the hospital."
            ]
          },
          {
            "parts": [
              "Six small bus stops were placed along Hospital Road, three on each side."
            ]
          },
          {
            "parts": [
              "A single car park for both staff and the public stood to the east of this road, just below the Ring Road."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "By 2010, traffic flow had been redesigned more systematically."
            ]
          },
          {
            "parts": [
              "A roundabout had been built at each end of Hospital Road, one at its junction with City Road and the other where it joined the Ring Road."
            ]
          },
          {
            "parts": [
              "The bus stops had been removed and replaced by a bus station on the western side, with access links to both roundabouts."
            ]
          },
          {
            "parts": [
              "Parking was also separated: the staff car park occupied the area east of Hospital Road, while a new public car park was constructed east of the hospital, reached directly from the Ring Road."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這兩幅地圖比較了 2007 年和 2010 年通往一所城市醫院的道路通達情況。",
      "整體而言，該區佈局被大幅重新規劃：新增了兩個迴旋處和一個巴士總站，而原本供員工和公眾共同使用的停車場則被分成員工停車場和公眾停車場。然而，三條主要道路的位置保持不變。",
      "2007 年，醫院路從城市路向北延伸至環路，而環路圍繞著醫院。六個小型巴士站沿醫院路設置，左右兩側各三個。一個供員工和公眾共同使用的停車場位於這條路以東、環路正下方。",
      "到 2010 年，交通流線已被更有系統地重新設計。醫院路兩端各建了一個迴旋處，一個位於它與城市路的交界處，另一個位於它與環路相接的位置。原有巴士站被移除，並由西側的一個巴士總站取代，而該巴士總站有道路連接至兩個迴旋處。停車安排也被分開：員工停車場佔據醫院路以東的區域，而一個新的公眾停車場則建於醫院東側，可直接從環路進入。"
    ],
