    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The two plans illustrate the current layout of a university sports centre and its proposed redevelopment."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, the centre is expected to expand westwards and eastwards, replacing both outdoor court areas with indoor facilities."
            ]
          },
          {
            "parts": [
              "The existing central core, including the 25-metre pool, reception, original changing room and seating area, will remain largely unchanged, while the gym will be enlarged and new leisure and commercial amenities will be added."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "At present, the sports centre consists of a compact rectangular building."
            ]
          },
          {
            "parts": [
              "A 25-metre pool occupies the middle, with a gym directly to its north."
            ]
          },
          {
            "parts": [
              "On the western side of the pool there is a changing room, whereas seating is located to the east."
            ]
          },
          {
            "parts": [
              "The reception area stands at the southern entrance, and the building is flanked by outdoor courts on both sides."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "After redevelopment, the western courts will be replaced by a large leisure pool, with an additional changing room and a sports shop to its south."
            ]
          },
          {
            "parts": [
              "On the eastern side, the courts will give way to a sports hall, two dance studios, a café and another changing room."
            ]
          },
          {
            "parts": [
              "The gym will also be extended across the northern part of the complex."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這兩張平面圖說明一所大學體育中心目前的布局，以及其擬議重建後的樣。",
      "整體而言，該中心預計會向西和向東擴展，並用室內設施取代兩側的戶外球場區。現有的中央核心區，包括 25 米泳池、接待處、原有更衣室和座位區，將大致保持不變；同時，健身房會擴大，並會增設新的休閒和商業設施。",
      "目前，該體育中心由一座緊湊的矩形建築組成。一個 25 米泳池位於中間，其正北方是健身房。泳池西側設有更衣室，而座位區位於東側。接待處位於南面的入口處，而建築兩側各有一片戶外球場。",
      "重建後，西側球場將被一個大型休閒泳池取代，其南面會新增一間更衣室和一間體育用品商店。在東側，球場將讓位給一個體育館、兩間舞蹈室、一間咖啡廳和另一間更衣室。健身房也將沿著建築群北部擴建。"
    ],
