    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The two plans illustrate the layout of Grange Park when it opened in 1920 and its arrangement today."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, the park has been substantially modernised, with recreational facilities such as an amphitheatre, café, children’s play area and underground parking added."
            ]
          },
          {
            "parts": [
              "However, the two main entrances on Arnold Avenue and Eldon Street have been retained, and rose gardens remain important, although they have been reduced and reorganised."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 1920, the park had a formal layout."
            ]
          },
          {
            "parts": [
              "A fountain stood at its centre, while a stage for musicians occupied the western side."
            ]
          },
          {
            "parts": [
              "Three rose gardens were located in the northwest, northeast and southwest corners, and seating was distributed around the edges."
            ]
          },
          {
            "parts": [
              "The eastern half contained a pond for water plants in the northeast and a glasshouse in the southeast."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "Today, the central fountain has been replaced by a square rose garden, surrounded by seats on all four sides."
            ]
          },
          {
            "parts": [
              "The former musicians’ stage has given way to a larger amphitheatre for concerts."
            ]
          },
          {
            "parts": [
              "On the eastern side, the old pond and glasshouse have disappeared; in their place are a café, a children’s play area and a water feature."
            ]
          },
          {
            "parts": [
              "A new entrance to an underground car park has also been introduced from the southeast."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這兩張平面圖展示了格蘭奇公園在 1920 年首次開放時的布局，以及它今天的安排。",
      "整體而言，該公園已大幅現代化，新增了露天劇場、咖啡館、兒童遊樂區和地下停車場等休閒設施。然而，位於阿諾德大道和埃爾登街的兩個主要入口被保留下來，而玫瑰園仍然是重要元素，儘管它們的數量已減少並被重新安排。",
      "在 1920 年，該公園具有較正式的布局。一座噴泉位於公園中央，而音樂家表演台則佔據西側位置。三個玫瑰園分別位於西北角、東北角和西南角，座位則分布在公園邊緣一帶。公園東半部包含位於東北方的水生植物池，以及位於東南方的玻璃溫室。",
      "如今，中央噴泉已被一個方形玫瑰園取代，而其四周均設有座位。原本的音樂家表演台已被一個更大的露天音樂會劇場取代。在東側，舊有的池塘和玻璃溫室已經消失；取而代之的是咖啡館、兒童遊樂區和水景設施。此外，東南方也新增了一個通往地下停車場的入口。"
    ],
