    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The two maps compare an island before and after the construction of tourist facilities."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, the island has been transformed from a largely undeveloped natural area into a compact resort, with accommodation, catering facilities and transport links added mainly in the western and central sections."
            ]
          },
          {
            "parts": [
              "However, the beach and most palm-tree areas have been retained, while the eastern end remains largely untouched."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "Before development, the island contained only natural features."
            ]
          },
          {
            "parts": [
              "A beach lay on the western shore, and groups of palm trees were scattered across the middle and, more densely, towards the east."
            ]
          },
          {
            "parts": [
              "There were no buildings, roads, paths or landing facilities, so access to and movement around the island were not formally provided."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "Following construction, two clusters of accommodation huts have been built: one close to the beach in the west and another around an open central area."
            ]
          },
          {
            "parts": [
              "These are linked by footpaths, one of which also runs to the beach, now marked for swimming."
            ]
          },
          {
            "parts": [
              "A reception building stands near the centre, with a restaurant just to its north."
            ]
          },
          {
            "parts": [
              "To the south, a pier has been added for boats, and vehicle tracks now connect it with both main service buildings."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這兩張地圖比較了一個島嶼在旅遊設施建設前後的情況。",
      "整體而言，這座島已經由一個基本未開發的自然區域轉變成一個小型度假區，住宿、餐飲設施和交通連接主要集中在西部和中部地區。然而，海灘和大部分棕櫚樹區域被保留下來，而島的東端基本上仍未受到改動。",
      "在開發前，這座島只包含自然特徵。一片海灘位於西岸，而棕櫚樹群分布在島的中部，並且在東部一帶更加密集。圖中沒有建築物、道路、小徑或登岸設施，因此島上的進出和內部移動並沒有正式的安排。",
      "建設完成後，兩組住宿小屋被建成：一組靠近西部的海灘，另一組則圍繞中部的一片開放區域。這些住宿小屋由步行小徑連接，其中一條小徑也通向海灘，而海灘現在被標示為游泳區。一座接待處位於島的中部附近，其北面緊鄰一間餐廳。在南部，一座供船隻使用的碼頭已被增設，而車道現在把碼頭與兩座主要服務建築連接起來。"
    ],
