    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The tables present changes in the population of New York City as a whole and compare Manhattan with the other four districts between 1800 and 2000."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, the city’s population rose dramatically across the two centuries, but the balance shifted sharply away from Manhattan."
            ]
          },
          {
            "parts": [
              "While Manhattan made up more than three quarters of New York’s residents in 1800, the other districts accounted for over four fifths by 2000."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 1800, New York City had only 79,216 inhabitants."
            ]
          },
          {
            "parts": [
              "By 1900 this figure had increased to 3,437,202, before reaching 8,009,185 in 2000."
            ]
          },
          {
            "parts": [
              "The first century therefore saw the more explosive expansion, with the population multiplying more than fortyfold; over the following hundred years it still grew substantially, though by a little over twice."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "Manhattan followed a different path from the rest of the city."
            ]
          },
          {
            "parts": [
              "Its population climbed from 60,515 in 1800 to 1,850,093 in 1900, but then declined to 1,538,096 by 2000."
            ]
          },
          {
            "parts": [
              "Its share consequently fell from 76% to 54%, and finally to just 19%."
            ]
          },
          {
            "parts": [
              "By contrast, the other districts grew continuously, from 18,701 to 1,587,109 and then to 6,471,089, raising their combined share from 24% to 81%."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這些表格呈現了 1800 年至 2000 年間整個紐約市人口的變化，並將曼哈頓與其他四個區作比較。",
      "整體而言，在這兩個世紀中，該市人口大幅上升，但人口分布的重心明顯從曼哈頓轉移開來。雖然曼哈頓在 1800 年佔紐約居民的四分之三以上，但到 2000 年，其他區已佔超過五分之四。",
      "1800 年，紐約市只有 79,216 名居民。到 1900 年，這一數字已增至 3,437,202 ，之後在 2000 年達到 8,009,185 。因此，第一個世紀出現了更爆炸性的增長，人口增加了四十多倍；在接下來的一百年中，人口仍然大幅增長，儘管只是略多於兩倍。",
      "曼哈頓的發展路徑與城市其他地區不同。其人口從 1800 年的 60,515 上升至 1900 年的 1,850,093 ，但到 2000 年又下降至。因此，其所佔比例從 76% 下降至 54% ，最後降至僅 19% 。相比之下，其他區的人口持續增長，從 18,701 上升至 1,587,109 ，然後再增至6,471,089 ，使它們的合計比例從 24% 上升至 81% 。"
    ],
