    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The tables compare sales of Fairtrade-labelled coffee and bananas, measured in millions of euros, in five European countries in 1999 and 2004."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, coffee sales increased in every market, with the UK recording by far the most striking rise and becoming the leading purchaser by 2004."
            ]
          },
          {
            "parts": [
              "Banana sales showed a less even pattern: Switzerland remained dominant and grew sharply, whereas Sweden and Denmark experienced declines."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "Regarding coffee, Switzerland had the highest figure in 1999, at 3 million euros, followed by Denmark at 1.8 million and the UK at 1.5 million."
            ]
          },
          {
            "parts": [
              "By 2004, however, the UK had surged to 20 million euros, more than three times Switzerland’s figure of 6 million."
            ]
          },
          {
            "parts": [
              "The remaining countries saw only modest growth, with Denmark edging up to 2 million, Belgium to 1.7 million and Sweden to 1 million."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "Banana sales were led by Switzerland in both years, rising from 15 to 47 million euros, which was far ahead of all other markets."
            ]
          },
          {
            "parts": [
              "The UK and Belgium also increased substantially, reaching 5.5 million and 4 million respectively in 2004."
            ]
          },
          {
            "parts": [
              "By contrast, Sweden fell from 1.8 to 1 million, while Denmark dropped from 2 to 0.9 million, becoming the smallest market."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這些表格比較了 1999 年和 2004 年五個歐洲國家的公平貿易標籤咖啡和香蕉銷售額，單位為百萬歐元。",
      "整體而言，咖啡銷售額在每個市場都有上升，其中英國的升幅最為顯著，並在 2004 年成為最大的購買國。香蕉銷售額的變化則沒有那麼一致：瑞士仍然佔主導地位並大幅增長，而瑞典和丹麥則出現下降。",
      "就咖啡而言，瑞士在 1999 年的銷售額最高，為 300 萬歐元，其次是丹麥的 180 萬歐元和英國的 150 萬歐元。然而，到 2004 年，英國銷售額激增至 2,000 萬歐元，是瑞士 600 萬歐元的三倍多。其餘國家只錄得溫和增長，其中丹麥微升至 200 萬歐元，比利時升至 170 萬歐元，瑞典則升至 100 萬歐元。",
      "香蕉銷售額在兩個年份都由瑞士領先，從 1,500 萬歐元上升至 4,700 萬歐元，遠高於所有其他市場。英國和比利時也大幅增長，在 2004 年分別達到 550 萬歐元和 400 萬歐元。相比之下，瑞典從 180 萬歐元下降至 100 萬歐元，而丹麥則從 200 萬歐元跌至 90萬歐元，成為最小的市場。"
    ],
