    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The table presents data on the number of nights spent in Germany by domestic and international tourists between 2016 and 2022, measured in millions."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, domestic tourism accounted for far more overnight stays than international tourism throughout the period."
            ]
          },
          {
            "parts": [
              "Both categories rose steadily until 2019, before falling sharply in 2020; although they recovered strongly by 2022, neither returned fully to its pre-decline peak."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "From 2016 to 2019, domestic-tourist nights increased consistently, rising from 366.4 million to 405.7 million."
            ]
          },
          {
            "parts": [
              "The international figure followed a similar but much smaller upward trend, climbing from 80.8 million to 89.9 million over the same years."
            ]
          },
          {
            "parts": [
              "As a result, domestic stays were roughly four and a half times as high as overseas stays during this initial period."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "The pattern changed markedly after 2019."
            ]
          },
          {
            "parts": [
              "Domestic nights dropped to 270.3 million in 2020, a fall of more than 130 million, before edging up to 279.23 million in 2021."
            ]
          },
          {
            "parts": [
              "International nights fell even more steeply in proportional terms, plunging from 89.9 million in 2019 to 32 million in 2020 and then slipping to 31.01 million in 2021."
            ]
          },
          {
            "parts": [
              "By 2022, domestic and international figures had rebounded to 382.62 million and 68.09 million respectively, but both remained below their 2019 levels."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這個表格呈現了 2016 年至 2022 年間，本地及國際遊客在德國逗留晚數的數據，單位為百萬晚。",
      "整體而言，在整個時期內，本地旅遊所佔的過夜住宿晚數遠遠高於國際旅遊。兩個類別都穩步上升至 2019 年，之後在 2020 年急劇下跌；雖然到 2022 年兩者均明顯回升，但都未完全恢復至下跌前的高峰。",
      "從 2016 年至 2019 年，本地遊客住宿晚數持續上升，從 3.664 億晚增至 4.057 億晚。國際遊客的數字也呈現相似但規模小得多的上升趨勢，同期從 8,080 萬晚增至 8,990 萬晚。因此，在這一初期階段，本地住宿晚數大約是海外遊客住宿晚數的四倍半。",
      "2019 年之後，這一模式出現了明顯變化。本地遊客住宿晚數在 2020 年跌至 2.703 億晚，下降超過 1.3 億晚，之後在 2021 年小幅回升至 2.7923 億晚。按比例來看，國際遊客住宿晚數跌幅更為陡峭，從 2019 年的 8,990 萬晚急跌至2020 年的 3,200 萬晚，之後在 2021 年再微跌至 3,101 萬晚。到 2022 年，本地及國際遊客住宿晚數分別反彈至 3.8262 億晚和 6,809 萬晚，但兩者仍低於 2019 年的水平。"
    ],
