    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The table compares the global market shares of mobile phone sales held by several manufacturers in 2005 and 2006."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, Nokia remained the clear market leader and slightly strengthened its position, while Motorola recorded the most notable gain among the named companies."
            ]
          },
          {
            "parts": [
              "By contrast, Samsung, LG, BenQ Mobile and the collective “Others” category all lost market share; Sony Ericsson was the only smaller named brand to grow."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 2005, Nokia accounted for 32.5% of worldwide sales, almost twice Motorola’s share of 17.7% and well ahead of Samsung, at 12.7%."
            ]
          },
          {
            "parts": [
              "One year later, Nokia had risen to 35%, widening its lead despite Motorola’s increase to 21.1%."
            ]
          },
          {
            "parts": [
              "Motorola’s rise, at 3.4 percentage points, was the largest improvement in the table, whereas Samsung slipped slightly to 11.8%."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "The remaining named manufacturers held much smaller shares."
            ]
          },
          {
            "parts": [
              "Sony Ericsson rose from 6.3% to 7.4%, overtaking LG, whose figure declined marginally from 6.7% to 6.3%."
            ]
          },
          {
            "parts": [
              "The steepest fall was seen in BenQ Mobile, which more than halved from 4.9% to 2.4%."
            ]
          },
          {
            "parts": [
              "Other manufacturers also became less significant collectively, dropping from 19.2% to 16.2%."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這張表比較了數間手機製造商在 2005 年和 2006 年所佔的全球手機銷售市場份額。Overview （總覽）Main Feature 1 （主要特徵一）。",
      "整體而言， Nokia 仍然是明顯的市場領導者，並略微鞏固了其地位；而在所有列名公司之中， Motorola 錄得最顯著的增長。Main Feature 2 （主要特徵二）。相比之下， Samsung 、 LG 、 BenQ Mobile 以及合併計算的「其他」類別均失去市場份額； Sony Ericsson 則是較小型列名品牌中唯一錄得增長的一間。Body Paragraph 1 （正文第一段）Leading Companies Details （主要公司細節）。",
      "2005 年， Nokia 佔全球銷售的 32.5% ，幾乎是 Motorola 17.7% 的兩倍，並遠高於Samsung 的 12.7% 。一年後， Nokia 上升至 35% ；儘管 Motorola 也增至 21.1% ， Nokia 仍進一步擴大其領先優勢。Motorola 上升了 3.4 個百分點，是表中最大增幅；相反， Samsung 則輕微下跌至 11.8% 。Body Paragraph 2 （正文第二段）Smaller Companies and Others （較小公司及其他類別）。",
      "其餘列名製造商所佔的市場份額明顯較小。Sony Ericsson 從 6.3% 上升至 7.4% ，並超越了 LG ；後者的數字則由 6.7% 輕微下降至 6.3% 。最大跌幅出現在 BenQ Mobile ，其市場份額由 4.9% 跌至 2.4% ，縮減了一半以上。其他製造商合計所佔的重要性亦有所下降，從 19.2% 跌至 16.2% 。"
    ],
