    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The table compares the percentages of first-year students in Economics, Law and Commerce who rated five aspects of their course as “very good”."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, Commerce received the strongest evaluations, leading or sharing first place in every aspect."
            ]
          },
          {
            "parts": [
              "Economics was rated highly for teaching and tutor support but much less favourably for pre-course information and resources, whereas Law showed a more balanced pattern, with teaching quality its weakest area."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In terms of teaching-related measures, Economics and Commerce both recorded 95% for teaching quality, far above Law at 67%."
            ]
          },
          {
            "parts": [
              "Tutor support followed a similar pattern: Commerce was marginally ahead at 93%, with Economics close behind at 92%, while Law was lower, though still fairly positive, at 79%."
            ]
          },
          {
            "parts": [
              "These figures made Economics and Commerce the clear leaders in these two areas."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "For the remaining aspects, Commerce again stood out."
            ]
          },
          {
            "parts": [
              "It achieved 95% for pre-course information, compared with 72% for Law and just 55% for Economics."
            ]
          },
          {
            "parts": [
              "The same hierarchy appeared for printed resources, at 81%, 70% and 59%, respectively."
            ]
          },
          {
            "parts": [
              "Other resources were also rated most highly in Commerce, at 85%, followed by Law at 80%, leaving Economics clearly behind at 62%."
            ]
          }
        ]
      }
    ],
    "translation": [
      "該表格比較了經濟學、法律和商科三個課程中，一年級學生把其課程五個方面評為「非常好」的比例。",
      "整體而言，商科獲得最強的評價，在每一個方面都位列第一或並列第一。經濟學在教學質素和導師支援方面評價很高，但在課前資訊和資源方面明顯較不理想；相比之下，法律的表現較為均衡，而教學質素是其最弱的一項。",
      "在教學相關指標方面，經濟學和商科的教學質素同樣錄得 95% ，遠高於法律的 67% 。導師支援呈現相似模式：商科以 93% 略微領先，經濟學以 92% 緊隨其後，而法律則較低，儘管 79% 仍算相當正面。這些數字使經濟學和商科在這兩個方面明顯領先。",
      "至於其餘方面，商科再次突出。它在課前資訊方面達到 95% ，相比之下，法律為 72% ，經濟學只有 55% 。印刷資源方面也出現相同排序，商科、法律和經濟學分別為 81% 、 70% 和 59%。其他資源方面，商科亦獲最高評價，達 85% ；法律以 80% 居次，而經濟學則以62% 明顯落後。"
    ],
