    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The table compares international tourist arrivals, measured in millions, in the listed destinations in 2009 and 2010, together with the percentage change over the period."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, France remained the most visited destination, despite recording no growth."
            ]
          },
          {
            "parts": [
              "Most places attracted more tourists in the second year, but the increases were generally modest among the larger markets and far stronger among Germany, China and Turkey."
            ]
          },
          {
            "parts": [
              "Hong Kong was the only destination to decline."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "Among the leading destinations, France received 76 million tourists in both years, staying well ahead of the US, whose figure edged up from 66 to 67 million."
            ]
          },
          {
            "parts": [
              "Spain and the UK were level at 55 million in 2009, but the UK grew more quickly, reaching 57 million and narrowly overtaking Spain, which rose to 56 million."
            ]
          },
          {
            "parts": [
              "Italy also increased slightly, from 44 to 45 million."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "The remaining destinations showed much sharper relative changes."
            ]
          },
          {
            "parts": [
              "Turkey, China and Germany each gained 12 million arrivals, climbing from 33 to 45 million, 22 to 34 million and 11 to 23 million respectively."
            ]
          },
          {
            "parts": [
              "Because Germany started from the lowest base, this represented the largest percentage rise, at 109%."
            ]
          },
          {
            "parts": [
              "By contrast, Hong Kong fell from 10 to 9 million, a decrease of 11%."
            ]
          }
        ]
      }
    ],
    "translation": [
      "該表格比較了所列目的地在 2009 年和 2010 年的國際遊客到訪人數，以百萬為單位，並展示了期間的百分比變化。",
      "整體而言，法國雖然沒有錄得增長，但仍然是最多遊客到訪的目的地。大部分地區在第二年吸引了更多遊客，但較大型市場的升幅普遍溫和，而德國、中國和土耳其的增長則強勁得多。香港是唯一出現下跌的目的地。",
      "在主要目的地之中，法國兩年均接待了 7,600 萬名遊客，仍然大幅領先美國；而美國的數字則由 6,600 萬微升至 6,700 萬。西班牙和英國在 2009 年同為 5,500 萬，但英國增長較快，達到 5,700 萬，並以輕微差距超越西班牙；西班牙則上升至 5,600 萬。意大利亦輕微上升，由 4,400 萬增至 4,500 萬。",
      "其餘目的地則呈現出更明顯的相對變化。土耳其、中國和德國的到訪人數均增加了 1,200 萬，分別由 3,300 萬升至 4,500萬、由 2,200 萬升至 3,400 萬，以及由 1,100 萬升至 2,300 萬。由於德國的起點最低，因此這代表了最大的百分比升幅，達 109% 。相比之下，香港由 1,000 萬下降至 900 萬，跌幅為 11% 。"
    ],
