    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The table compares the percentage of management posts occupied by women in finance, manufacturing, IT and hospitality in a European country in 2006."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, women were most strongly represented in hospitality and least represented in manufacturing across the three levels."
            ]
          },
          {
            "parts": [
              "In addition, their share generally decreased as seniority rose, although hospitality was an exception at the top level, where the proportion of female CEOs slightly exceeded that of female executives."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "Among managers, hospitality had by far the highest figure, at 33.14%, roughly twice the shares recorded in finance and IT, which were almost identical at 16.39% and 16.04% respectively."
            ]
          },
          {
            "parts": [
              "Manufacturing was noticeably lower, with women making up only 9% of managers."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "A similar ranking can be seen among executives and CEOs, though the percentages were smaller."
            ]
          },
          {
            "parts": [
              "In hospitality, women accounted for 19.9% of executives and 20.6% of CEOs, far ahead of IT, where the equivalent figures were 12.82% and 6.58%."
            ]
          },
          {
            "parts": [
              "Female representation was much weaker in finance, at 4.58% for executives and just 1.98% for CEOs."
            ]
          },
          {
            "parts": [
              "Manufacturing had the lowest levels overall, with only 1.98% of executives and 1.21% of CEOs being women."
            ]
          }
        ]
      }
    ],
    "translation": [
      "該表格比較了 2006 年某歐洲國家中，女性在金融、製造業、資訊科技和酒店款待業所佔管理職位的百分比。",
      "整體而言，在三個職級中，女性在酒店款待業的代表性最高，而在製造業的代表性最低。此外，女性所佔比例通常隨職級上升而下降；不過，酒店款待業在最高層級是一個例外，女性行政總裁的比例略高於女性行政人員。",
      "在經理職位中，酒店款待業的數字遠高於其他行業，達 33.14% ，大約是金融和資訊科技業的兩倍；後兩者的比例幾乎相同，分別為 16.39% 和 16.04% 。製造業則明顯較低，女性只佔經理職位的 9% 。",
      "在行政人員和行政總裁層面，也可以看到相似的排名，不過比例整體較低。在酒店款待業中，女性佔行政人員的 19.9% ，並佔行政總裁的 20.6% ，遠高於資訊科技業；後者相應數字為 12.82% 和 6.58% 。金融業的女性代表性則弱得多，女性行政人員佔 4.58% ，而女性行政總裁僅佔。製造業整體水平最低，女性只佔行政人員的 1.98% ，並只佔行政總裁的 1.21%。"
    ],
