    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The table compares the daily per-person calorie intake from rice, wheat and maize in Cambodia, Poland, Egypt and Mexico."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, each country shows a clear dependence on a different staple: rice in Cambodia, wheat in Poland and Egypt, and maize in Mexico."
            ]
          },
          {
            "parts": [
              "Egypt records the broadest consumption across all three foods, while Poland has the narrowest pattern, with no calories from maize."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "Rice is overwhelmingly dominant in Cambodia, at 1,445 calories per person per day, which is nearly three times Egypt's figure of 501."
            ]
          },
          {
            "parts": [
              "The two remaining countries consume little rice: Mexico stands at 57 calories, while Poland records only 19."
            ]
          },
          {
            "parts": [
              "Wheat, by contrast, is barely eaten in Cambodia, at just 18 calories."
            ]
          },
          {
            "parts": [
              "It is the main source in Egypt and Poland, at 1,095 and 865 calories respectively, whereas Mexico's figure is much lower, at 275."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "Maize consumption follows a different pattern."
            ]
          },
          {
            "parts": [
              "Mexico records the highest intake, at 1,083 calories, far ahead of Egypt's 578 and over ten times Cambodia's 103."
            ]
          },
          {
            "parts": [
              "Poland, however, reports no maize consumption at all."
            ]
          }
        ]
      }
    ],
    "translation": [
      "該表比較了柬埔寨、波蘭、埃及和墨西哥四國人民每日每人從米、小麥和玉米中攝取的卡路里。",
      "整體而言，每個國家都明顯依賴不同的主食：柬埔寨主要依賴米，波蘭和埃及主要依賴小麥，而墨西哥則主要依賴玉米。埃及在三種食物中都有較廣泛的攝取，而波蘭的飲食模式最狹窄，完全沒有來自玉米的卡路里。",
      "米在柬埔寨佔絕對主導地位，達到每日每人 1,445 卡路里，幾乎是埃及 501 卡路里的三倍。其餘兩國的米攝取量很低：墨西哥為 57 卡路里，而波蘭只有 19 卡路里。相比之下，小麥在柬埔寨幾乎不被食用，只有 18 卡路里。小麥是埃及和波蘭的主要來源，分別為 1,095 和 865 卡路里，而墨西哥的數字則低得多，為 275 卡路里。",
      "玉米的攝取情況則呈現不同模式。墨西哥的玉米攝取量最高，達 1,083 卡路里，遠高於埃及的 578 卡路里，也超過柬埔寨 103 卡路里的十倍。然而，波蘭完全沒有玉米攝取量。"
    ],
