    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The table compares the proportions of pupils enrolled in four types of secondary school in 2000, 2005 and 2009."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, attendance shifted markedly away from voluntary-controlled and grammar schools towards community schools."
            ]
          },
          {
            "parts": [
              "While voluntary-controlled schools had by far the largest share at the beginning, community schools became the dominant type by 2009, and specialist schools remained the smallest or joint-smallest category throughout."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 2000, just over half of pupils attended voluntary-controlled schools, at 52%, making this sector more than twice as large as grammar schools, which accounted for 24%."
            ]
          },
          {
            "parts": [
              "Specialist and community schools each had 12%, so their combined share was equal to that of grammar schools alone."
            ]
          },
          {
            "parts": [
              "By 2005, however, voluntary-controlled schools had fallen to 38%, while community schools had climbed sharply to 32%, narrowing the gap between the two leading categories to only six percentage points."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "The change became more pronounced by 2009."
            ]
          },
          {
            "parts": [
              "Community schools rose further to 58%, almost five times their initial proportion."
            ]
          },
          {
            "parts": [
              "By contrast, voluntary-controlled schools dropped to 20%, less than half their 2000 figure."
            ]
          },
          {
            "parts": [
              "Grammar schools also declined steadily, from 24% to 12%, while specialist schools slipped only slightly, from 12% to 10%."
            ]
          }
        ]
      }
    ],
    "translation": [
      "該表格比較了 2000 年、 2005 年和 2009 年四類中學的學生就讀比例。",
      "整體而言，學生就讀比例明顯由志願控制學校和文法學校轉向社區學校。雖然志願控制學校在最初佔比遠遠最高，但到 2009 年，社區學校已成為最主要的類別，而專科學校在整段期間一直是最小或並列最小的類別。",
      "在 2000 年，剛過半數學生就讀於志願控制學校，比例為 52% ，使這一類別的佔比超過文法學校的兩倍；文法學校則佔 24% 。專科學校和社區學校各佔 12% ，因此兩者合計比例正好等同於文法學校單獨的比例。然而，到 2005 年，志願控制學校已下降至 38% ，而社區學校則大幅上升至 32%，使兩個主要類別之間的差距收窄至僅 6 個百分點。",
      "到 2009 年，這一變化變得更加明顯。社區學校進一步上升至 58% ，幾乎是其最初比例的五倍。相比之下，志願控制學校下降至 20% ，不到其 2000 年數字的一半。文法學校也持續下降，從 24% 跌至 12% ；而專科學校則只輕微下滑，從 12% 降至。"
    ],
