    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The graphics summarise Little Chalfont Library’s age profile, loan categories in 2016, and annual loan totals from 2007 to 2016."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, adults aged 18–64 made up the majority of members, while fiction was by far the dominant type of borrowing."
            ]
          },
          {
            "parts": [
              "Total lending rose across the period, despite a brief dip around 2013."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 2016, adults aged 18–64 accounted for 51% of members, more than twice the share of children, at 22%."
            ]
          },
          {
            "parts": [
              "Young adults and people aged 65 or over were smaller groups, at 15% and 12% respectively."
            ]
          },
          {
            "parts": [
              "Loans were concentrated in two categories: children’s fiction and adult fiction each represented 38%, together making up just over three quarters of all borrowing."
            ]
          },
          {
            "parts": [
              "Adult non-fiction was next, at 13%, whereas children’s non-fiction accounted for only 6%."
            ]
          },
          {
            "parts": [
              "Young adults and adult audio books stood at 2% each, and children’s DVDs were negligible, at 1%."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "Annual loans increased from just under 16,000 in 2007 to about 19,000 in 2008 and 2009."
            ]
          },
          {
            "parts": [
              "The figure then stayed mostly above 20,000 until 2012, fell slightly below this level in 2013, and recovered steadily to a peak of roughly 21,500 in 2016."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這些圖表概述了 Little Chalfont Library 的會員年齡分布、2016年的借閱類別，以及2007年至2016年間每年的總借閱量。",
      "整體而言，18至64歲的成年人佔會員的大多數，而小說明顯是最主要的借閱類型。儘管在2013年前後曾短暫下降，整體借閱量在整段期間仍然上升。",
      "在2016年，18至64歲的成年人佔會員的51%，是兒童比例22%的兩倍多。青年成人和65歲或以上人士則是較小的群體，分別佔15%和12%。借閱主要集中在兩個類別：兒童小說和成人小說各佔38%，兩者合計佔全部借閱量的四分之三多一點。成人非小說類排在其後，佔13%；相比之下，兒童非小說類只佔6%。青年成人類和成人有聲書各佔2%，而兒童 DVDs 幾乎可以忽略，只佔1%。",
      "每年借閱量由2007年的略低於16,000次，上升至2008年和2009年的約19,000次。此後，該數字到2012年大多維持在20,000次以上，2013年略跌至此水平以下，然後穩步回升，並在2016年達到約21,500次的高峰。"
    ],
