    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The pie chart shows where young people in an Australian town attend dance classes, while the bar chart compares the numbers of under-11s and 11- to 16-year-olds taking ballet, tap and modern dance."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, private studios are by far the most common venue, accounting for nearly half of all classes, whereas college-based studios represent the smallest share."
            ]
          },
          {
            "parts": [
              "In terms of dance style, ballet is clearly the leading choice among younger children, while modern dance is more popular with the older group; tap attracts broadly similar numbers in both age bands."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "Looking first at locations, 48% of classes are held in private studios, exactly twice the proportion taking place in after-school sessions in school halls, at 24%."
            ]
          },
          {
            "parts": [
              "Community halls and other venues make up a further 18%, leaving college-based studios with only 10%, or around one tenth of the total."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "Regarding class types, about 600 children under 11 attend ballet, compared with roughly 300 students aged 11–16."
            ]
          },
          {
            "parts": [
              "Modern dance shows the opposite pattern, with just under 300 younger participants but approximately 520 older ones."
            ]
          },
          {
            "parts": [
              "Tap is more evenly balanced, at around 450 under-11s and slightly over 400 students in the older age group."
            ]
          }
        ]
      }
    ],
    "translation": [
      "圓餅圖顯示澳洲某城鎮的年輕人在哪些地點上舞蹈課，而柱狀圖則比較了 11歲以下以及 11 至 16 歲學生參加芭蕾舞、踢踏舞和現代舞課程的人數。",
      "整體而言，私人舞蹈室是目前最常見的上課地點，佔所有課程的接近一半；相反，設於學院的舞蹈室所佔比例最小。就舞蹈類型而言，芭蕾舞明顯是較年幼兒童的首選，而現代舞則更受年齡較大的學生歡迎；踢踏舞在兩個年齡組中的人數大致相近。",
      "先看上課地點， 48% 的課程在私人舞蹈室舉行，這正好是學校禮堂課後課程比例的兩倍，後者為 24% 。社區禮堂和其他場地另佔 18% ，而學院舞蹈室只佔 10% ，即大約佔整體的十分之一。",
      "就課程類型而言，大約 600 名 11 歲以下兒童參加芭蕾舞課，相比之下， 11 至16 歲的學生約為 300 人。現代舞則呈現相反模式，較年幼組別的人數略低於 300 ，而較年長組別約有520 人。踢踏舞的人數分布較平均， 11 歲以下學生約為 450 人，而較年長組別則略高於 400 人。"
    ],
