    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The table compares the police budget in one area of Britain in 2017 and 2018 by funding source, while the pie charts show how the money was spent."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, the budget rose modestly over the two years."
            ]
          },
          {
            "parts": [
              "The national government remained the main source of funding, although the increase came chiefly from local taxes."
            ]
          },
          {
            "parts": [
              "In terms of expenditure, salaries continued to dominate the budget, but their share fell as technology took a larger proportion."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 2017, the total police budget stood at £304.7 million."
            ]
          },
          {
            "parts": [
              "Of this, £175.5 million came from the national government, far more than the £91.2 million raised through local taxes and the £38 million from other sources, such as grants."
            ]
          },
          {
            "parts": [
              "By 2018, the total had climbed to £318.6 million."
            ]
          },
          {
            "parts": [
              "Government funding increased only slightly, to £177.8 million, while local-tax revenue rose more sharply to £102.3 million."
            ]
          },
          {
            "parts": [
              "Other sources changed very little, reaching £38.5 million."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "Regarding spending, salaries accounted for three quarters of the budget in 2017, before declining to 69% in 2018."
            ]
          },
          {
            "parts": [
              "By contrast, technology almost doubled its share, rising from 8% to 14%, whereas buildings and transport remained unchanged at 17%."
            ]
          }
        ]
      }
    ],
    "translation": [
      "該表格按照資金來源比較了英國某地區在2017年和2018年的警察預算，而餅圖則顯示了這筆錢的支出方式。",
      "整體而言，這兩年間警察預算有小幅上升。中央政府仍然是主要資金來源，儘管預算增幅主要來自地方稅收。在支出方面，薪金仍然佔據預算的最大部分，但其比例有所下降，而科技支出所佔比例則增加了。",
      "2017年，警察總預算為3.047億英鎊。其中，1.755億英鎊來自中央政府，遠高於地方稅收籌得的9,120萬英鎊，以及來自其他來源如補助金的3,800萬英鎊。到2018年，總預算上升至3.186億英鎊。政府撥款只小幅增加至1.778億英鎊，而地方稅收則更明顯地上升至1.023億英鎊。其他來源變化很小，達到3,850萬英鎊。",
      "在支出方面，薪金在2017年佔預算的四分之三，之後在2018年下降至69%。相比之下，科技支出所佔比例幾乎翻倍，從8%上升至14%；而建築物和交通支出則保持不變，均為17%。"
    ],
