    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The bar chart compares the export earnings of a country in five product categories in 2015 and 2016, while the table indicates the percentage change in each category over the same period."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, export revenue rose in four of the five categories, with gems and jewellery being the only sector to decline."
            ]
          },
          {
            "parts": [
              "Petroleum products remained the largest earner in both years, whereas textiles, despite starting from the lowest base, recorded the fastest growth."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In 2015, petroleum products generated about $61 billion, slightly more than engineered goods, at roughly $58 billion."
            ]
          },
          {
            "parts": [
              "Both categories increased in 2016: the former rose modestly by 3% to around $63 billion, while the latter climbed more sharply, by 8.5%, to approximately $62 billion."
            ]
          },
          {
            "parts": [
              "Gems and jewellery followed a different path, falling from about $43 billion to roughly $41 billion, a decrease of 5.18%."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "Among the lower-earning categories, agricultural products changed very little, remaining at around $31 billion in both years after a marginal rise of 0.81%."
            ]
          },
          {
            "parts": [
              "Textiles, by contrast, grew markedly from about $26 billion to roughly $31 billion, representing a 15.24% increase and making it nearly equal to agricultural products by 2016."
            ]
          }
        ]
      }
    ],
    "translation": [
      "這張柱狀圖比較了一個國家在 2015 年和 2016 年五個產品類別的出口收入，而表格則顯示了同一期間每個類別出口價值的百分比變化。",
      "整體而言，五個類別中有四個的出口收入上升，只有寶石與珠寶這一類出現下降。石油產品在兩年中都是出口收入最高的類別；相反，紡織品雖然起點最低，卻錄得最快的增長。",
      "2015 年，石油產品創造了約 610 億美元的出口收入，略高於工程產品的約 580億美元。這兩個類別在 2016 年均有所上升：前者溫和增長 3% ，達到約 630 億美元；後者則上升更明顯，增幅為 8.5% ，達到約 620 億美元。寶石與珠寶則呈現不同走勢，從約 430 億美元下降至約 410 億美元，跌幅為。",
      "在收入較低的類別中，農產品變化非常小，在輕微上升 0.81% 後，兩年都維持在約 310 億美元左右。相比之下，紡織品從約 260 億美元顯著增長至約 310 億美元，增幅為 15.24% ，到2016 年幾乎與農產品持平。"
    ],
