    "paragraphs": [
      {
        "label": "Introduction",
        "sentences": [
          {
            "parts": [
              "The table and pie charts compare attendance at Ashdown Museum and visitors’ satisfaction levels in the years before and after its refurbishment."
            ]
          }
        ]
      },
      {
        "label": "Overview",
        "sentences": [
          {
            "parts": [
              "Overall, the museum became both more popular and more highly rated after the work was completed."
            ]
          },
          {
            "parts": [
              "The total number of visitors rose markedly, while positive responses replaced dissatisfaction as the dominant pattern."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 1",
        "sentences": [
          {
            "parts": [
              "In terms of attendance, the museum received 74,000 visitors before the refurbishment, but this figure increased to 92,000 in the following year, a rise of 18,000."
            ]
          },
          {
            "parts": [
              "The improvement in satisfaction was even more striking."
            ]
          },
          {
            "parts": [
              "Before the changes, only 15% of respondents said they were very satisfied and a further 30% were satisfied, meaning that positive feedback accounted for less than half of all responses."
            ]
          },
          {
            "parts": [
              "After refurbishment, however, these two categories climbed to 35% and 40%, respectively, so three quarters of visitors expressed satisfaction."
            ]
          }
        ]
      },
      {
        "label": "Body Paragraph 2",
        "sentences": [
          {
            "parts": [
              "By contrast, the proportion of dissatisfied visitors fell sharply."
            ]
          },
          {
            "parts": [
              "In the year before refurbishment, 40% reported being dissatisfied, making this the largest single group, while 10% were very dissatisfied."
            ]
          },
          {
            "parts": [
              "In the year after refurbishment, these figures dropped to 15% and 5%, respectively."
            ]
          },
          {
            "parts": [
              "The share giving no response remained unchanged at 5% in both years."
            ]
          }
        ]
      }
    ],
    "translation": [
      "該表格和圓餅圖比較了阿什當博物館翻新前後兩年中的參觀人數，以及訪客對參觀體驗的滿意程度。",
      "整體而言，翻新工程完成後，該博物館不但更受歡迎，也獲得了更高的評價。總訪客人數明顯上升，而正面回應也取代不滿意，成為主要的滿意度模式。",
      "就參觀人數而言，該博物館在翻新前一年接待了 74,000 名訪客，但在翻新後一年，這一數字上升至 92,000 ，增加了 18,000 人。滿意度方面的改善甚至更加明顯。在翻新前，只有 15% 的受訪者表示非常滿意，另有 30% 表示滿意，這意味著正面回饋佔所有回應不到一半。然而，翻新後，這兩個類別分別上升至 35% 和 40% ，因此有四分之三的訪客表達了滿意。",
      "相比之下，不滿意訪客的比例大幅下降。在翻新前一年， 40% 的訪客表示不滿意，使其成為最大的單一組別，而另有10% 表示非常不滿意。在翻新後一年，這兩項數字分別下降至 15% 和 5% 。沒有回應的比例在兩年中都保持在 5% ，沒有變化。"
    ],
